import AppKit
import Combine
import Darwin
import SwiftUI
import Testing
@testable import Notchline

struct NotchlineTests {
    /// A no-notch panel is one width across the whole working set.
    ///
    /// It used to measure itself, so it resized whenever the status changed or
    /// a turn started or finished — which on a menu bar reads as flicker rather
    /// than information. The set it has to hold still has changed: it is now
    /// the states an agent that is *connected* can be in, and a `Disconnected`
    /// pill is deliberately allowed to be narrower.
    @Test @MainActor
    func noNotchCompactIsOneFixedWidthAcrossTheWorkingSet() {
        for matrixCount in 1 ... 2 {
            var widths: Set<CGFloat> = []
            var heights: Set<CGFloat> = []
            for status in PanelMetrics.workingStatuses {
                for agent in AgentKind.allCases {
                    for trailingText in [nil, "0:07", "1:23", "00:00:00"] as [String?] {
                        for barHeight in [CGFloat(46), 38, 24] {
                            let size = PanelMetrics.size(
                                geometry: .noNotch,
                                isExpanded: false,
                                statusReadoutText: status.compactDisplayName,
                                trailing: CompactTrailingReading(timerText: trailingText),
                                centerOcclusionWidth: 0,
                                compactHeight: barHeight,
                                status: status,
                                matrixCount: matrixCount
                            )
                            widths.insert(size.width)
                            heights.insert(size.height)
                        }
                    }
                }
            }

            #expect(
                widths == [
                    PanelMetrics.fixedCompactWidth(
                        for: .running,
                        matrixCount: matrixCount
                    )
                ]
            )
            // Height still follows the menu bar; only width came loose.
            #expect(heights == [46, 38, 24])
        }
    }

    /// The three widths in the design, to the point.
    ///
    /// `docs/figma-design.md` §6.4 fixes them by measurement rather than by
    /// choice, so they are checkable here against the same fonts the app draws
    /// with. Golden numbers are usually the wrong assertion; here they are the
    /// contract — the doc names them, a Figma frame is drawn at them, and a
    /// change to padding or to the widest label is supposed to fail loudly
    /// rather than quietly move a pill that lives in the user's menu bar.
    ///
    /// It did exactly that when the horizontal padding went `24 → 12`: these
    /// were `220`, `242` and `160`, each `24` wider. The numbers below are the
    /// same composition re-measured, not a relaxation of it.
    @Test @MainActor
    func theFixedCompactWidthsAreTheOnesTheDesignMeasured() {
        #expect(PanelMetrics.fixedCompactWidth(for: .running, matrixCount: 1) == 196)
        #expect(PanelMetrics.fixedCompactWidth(for: .running, matrixCount: 2) == 218)
        #expect(
            PanelMetrics.fixedCompactWidth(for: .disconnected, matrixCount: 1) == 136
        )

        // Zero connected products is the grey resting mark, which takes the one
        // slot rather than adding one — so it must not be wider than one product.
        #expect(
            PanelMetrics.fixedCompactWidth(for: .disconnected, matrixCount: 0)
                == PanelMetrics.fixedCompactWidth(for: .disconnected, matrixCount: 1)
        )
    }

    /// The reservation has to actually fit, and not be so generous that it is
    /// holding space nothing can use.
    @Test @MainActor
    func theFixedWidthFitsEveryWorkingStatusWithItsLongestTimer() {
        var widest: CGFloat = 0
        for status in PanelMetrics.workingStatuses {
            let needed = PanelMetrics.compactChromeWidth
                + PanelMetrics.compactContentWidth(status)
            #expect(needed <= PanelMetrics.fixedCompactWidth(for: status, matrixCount: 1))
            widest = max(widest, needed)
        }
        // Only the rounding up should separate them.
        #expect(PanelMetrics.fixedCompactWidth(for: .running, matrixCount: 1) - widest < 1)

        // The maximiser is `Approval`, and it is worth naming: two working
        // states have longer *labels* — `Connected` and `Completed` — and both
        // lose because neither can be counting. Reserving the timer slot behind
        // the longest label rather than the longest timed one over-reserves.
        #expect(
            PanelMetrics.workingStatuses.max {
                PanelMetrics.compactContentWidth($0)
                    < PanelMetrics.compactContentWidth($1)
            } == .approvalNeeded
        )
        for longerWord in [MonitorStatus.connected, .completed] {
            #expect(
                PanelMetrics.compactLabelWidth(longerWord)
                    > PanelMetrics.compactLabelWidth(.approvalNeeded)
            )
            #expect(!longerWord.canShowElapsed)
            #expect(
                PanelMetrics.compactContentWidth(longerWord)
                    < PanelMetrics.compactContentWidth(.approvalNeeded)
            )
        }
    }

    /// `Disconnected` is the one state allowed to be narrower.
    ///
    /// Nothing follows it into the timer slot — a surface with nothing
    /// connected has no turn to count — so reserving one would leave a visibly
    /// empty pill beside a short word.
    @Test @MainActor
    func onlyDisconnectedIsNarrowerThanTheWorkingWidth() {
        let working = PanelMetrics.fixedCompactWidth(for: .running, matrixCount: 1)
        #expect(PanelMetrics.fixedCompactWidth(for: .disconnected, matrixCount: 1) < working)
        for status in PanelMetrics.workingStatuses {
            #expect(PanelMetrics.fixedCompactWidth(for: status, matrixCount: 1) == working)
        }
    }

    /// The collapsed surface reports on products, not on us.
    ///
    /// This is the invariant that replaced six thin states with two. The four
    /// retired ones stay in the enum because the expanded panel and Settings
    /// still say them, so the thing worth pinning is not that they are gone but
    /// that the *aggregate* can never return one — including from the seed the
    /// store starts with, which used to publish `Connecting`.
    @Test @MainActor
    func theCollapsedAggregateOnlyEverReachesTheSixReachableStatuses() {
        let retired: [MonitorStatus] = [
            .connecting, .setupRequired, .updateAgent, .unsupportedVersion
        ]
        for status in retired {
            #expect(!MonitorStatus.collapsedReachable.contains(status))
        }

        // Every availability, with and without presence, for one and two
        // products: the aggregate has to land inside the reachable set every time.
        let availabilities: [MonitorAvailability] = [
            .ready, .connecting, .setupRequired,
            .updateAgent, .unsupportedVersion, .disconnected
        ]
        for availability in availabilities {
            for presence in AgentPresence.allCases {
                let one = AgentSnapshot(
                    availability: availability,
                    sessions: [],
                    quota: .unavailable,
                    diagnostic: nil,
                    presence: presence
                )
                let merged = AgentSnapshotMerge.merge([one])
                #expect(MonitorStatus.collapsedReachable.contains(merged.status))
            }
        }

        #expect(
            MonitorStatus.collapsedReachable.contains(MonitorSnapshot.connecting.status)
        )
    }

    /// The retired states did not lose their words, only their place — and
    /// then their product names.
    ///
    /// Four of these used to be told which product they were about, so the
    /// panel could say `Codex disconnected`. None of them are any more: which
    /// product is unhealthy is Settings' job, where every product is listed
    /// with its own state beside it. The sentences stay pinned in their
    /// generic form because the expanded panel and the empty-list message
    /// still say them.
    @Test @MainActor
    func theRetiredThinStatesReadGenericallyWhereTheyStillAppear() {
        #expect(MonitorStatus.connecting.displayName == "Connecting")
        #expect(MonitorStatus.updateAgent.displayName == "Update required")
        #expect(MonitorStatus.unsupportedVersion.displayName == "Version unsupported")
        #expect(MonitorStatus.disconnected.displayName == "Disconnected")
        #expect(MonitorStatus.updateAgent.compactDisplayName == "Update")
        #expect(MonitorAvailability.disconnected.emptyListMessage == "Disconnected")
    }

    /// No label names a product, in either form, in any state.
    ///
    /// This is what let both widths stop folding over configured products.
    /// `Update Claude Code` was the widest compact label and it set the
    /// two-product pill width for a state Claude Code cannot reach (issue #29);
    /// `Claude Code version unsupported` was doing the same to the expanded
    /// panel, ~79pt of it, on every panel a Claude Code user ever opened. With
    /// no label naming a product, what widens either surface is a second matrix
    /// and the cut-out, and nothing else.
    @Test @MainActor
    func noStatusLabelNamesAProduct() {
        for status in MonitorStatus.allCases {
            for agent in AgentKind.allCases {
                #expect(!status.displayName.contains(agent.displayName))
                #expect(!status.compactDisplayName.contains(agent.displayName))
            }
        }
    }


    /// Grey is not a fourth product colour, and it must be the darkest thing here.
    ///
    /// The ordering is the whole reason `#151515` was picked: "an agent is
    /// connected" must never look dimmer than "nothing is connected", or the
    /// presence channel reads backwards. Asserted as relative luminance rather
    /// than as a hex string, because that is the property that has to hold.
    @Test @MainActor
    func theRestingGreyIsDarkerThanEitherProductsUnlitColour() {
        func luminance(_ ink: NotchPalette.MatrixInk) -> Double {
            func channel(_ value: Double) -> Double {
                value <= 0.03928
                    ? value / 12.92
                    : pow((value + 0.055) / 1.055, 2.4)
            }
            return 0.2126 * channel(ink.offRed)
                + 0.7152 * channel(ink.offGreen)
                + 0.0722 * channel(ink.offBlue)
        }

        let resting = luminance(NotchPalette.restingInk)
        #expect(resting <= luminance(NotchPalette.codexInk))
        #expect(resting <= luminance(NotchPalette.claudeCodeInk))

        // The resting mark cannot light: with nothing connected there is
        // nothing that could be running.
        #expect(NotchPalette.restingInk.on == NotchPalette.restingInk.off)
        // Each product's does.
        for agent in AgentKind.allCases {
            #expect(NotchPalette.ink(for: agent).on != NotchPalette.ink(for: agent).off)
        }
        // And the two products are told apart by hue, not by brightness.
        #expect(NotchPalette.ink(for: .codex) != NotchPalette.ink(for: .claudeCode))
    }

    /// The legend's seam runs the way the app's own mark does.
    ///
    /// This is the first asymmetric thing the matrix has ever drawn. All four
    /// patterns are symmetric top to bottom — a checkerboard, a centre cell,
    /// and two uniform fields — so the view's `isFlipped` has never been
    /// observable and nothing would have caught it being wrong. The seam
    /// would: mirrored, it runs upper-left to lower-right and the legend stops
    /// looking like the icon.
    ///
    /// Asserted on the path rather than on rendered pixels because the path is
    /// what the code decides; the row and column arithmetic beside it is the
    /// other half of the same claim.
    @Test @MainActor
    func theSplitMatrixCutsOnTheSameDiagonalAsTheMark() {
        // Codex above the seam, Claude Code below — the mark's own order.
        #expect(NotchPalette.MatrixSplit.products.above == NotchPalette.codexInk)
        #expect(NotchPalette.MatrixSplit.products.below == NotchPalette.claudeCodeInk)

        // Row 0 is the top row, which is what makes "above" mean above.
        #expect(MatrixIndicatorView(frame: .zero).isFlipped)

        // Three cells a side, three on the seam itself.
        let sides = (0 ..< 9).map { MatrixIndicatorView.DiagonalSide.of(cell: $0) }
        #expect(sides == [
            .above, .above, .onSeam,
            .above, .onSeam, .below,
            .onSeam, .below, .below
        ])

        // The trailing half is the lower-right one: y grows downwards, so the
        // corner it must cover is the bottom-right and the one it must leave
        // alone is the top-left.
        let edge: CGFloat = 27
        let half = MatrixIndicatorView.trailingHalf(edge: edge, radius: 2)
        #expect(half.contains(CGPoint(x: edge * 0.8, y: edge * 0.8)))
        #expect(!half.contains(CGPoint(x: edge * 0.2, y: edge * 0.2)))
        // And it is a half, not a quadrant: it reaches both ends of the seam,
        // and neither of the two cells the seam separates is on it. Every
        // point here is clear of the line x + y = edge, which `contains` is
        // entitled to answer either way.
        #expect(half.contains(CGPoint(x: edge * 0.9, y: edge * 0.5)))
        #expect(half.contains(CGPoint(x: edge * 0.5, y: edge * 0.9)))
        #expect(!half.contains(CGPoint(x: edge * 0.5, y: edge * 0.1)))
        #expect(!half.contains(CGPoint(x: edge * 0.1, y: edge * 0.5)))
    }

    /// Two marks showing the same pattern show it in sync.
    ///
    /// The two products start their turns whenever they start them, so a Codex
    /// session going Running and a Claude Code one going Running some seconds
    /// later used to leave two identical curves running against each other:
    /// the same wave twice, out of step, which reads as two unrelated things
    /// flickering rather than as one state said about two products. Phase came
    /// from the moment the layers happened to be built.
    ///
    /// It comes from the clock instead, so it is a property of *when it is*
    /// rather than of when each mark was made. Two marks in the same state
    /// therefore differ by a whole number of periods, which is the same phase.
    @Test @MainActor
    func marksShowingTheSamePatternShowItInSync() async throws {
        /// How far a phase is from the nearest whole-period boundary.
        ///
        /// Not `phase % period == 0`: a period of `1.2` has no exact binary
        /// representation, so a boundary lands either just above zero or just
        /// below a whole period, and only the distance to the nearer end is
        /// the same claim at both.
        func offGrid(_ phase: CFTimeInterval, _ period: TimeInterval) -> Double {
            let remainder = phase.truncatingRemainder(dividingBy: period)
            return min(remainder, period - remainder)
        }

        func beginTimes(of state: NotchMatrixState, ink: NotchPalette.MatrixInk)
            throws -> [CFTimeInterval]
        {
            let view = MatrixIndicatorView(frame: CGRect(x: 0, y: 0, width: 16, height: 16))
            view.apply(state: state, size: 16, isAnimated: true, ink: ink)
            let cells = try #require(view.layer?.sublayers).flatMap { $0.sublayers ?? [] }
            return cells.compactMap {
                $0.animation(forKey: "notch.matrix.opacity")?.beginTime
            }
        }

        // One mark first, then the other a beat later — the sequence that used
        // to desynchronise them.
        let builtCodexAt = CACurrentMediaTime()
        let codex = try beginTimes(of: .running, ink: NotchPalette.codexInk)
        try await Task.sleep(for: .milliseconds(120))
        let builtClaudeAt = CACurrentMediaTime()
        let claudeCode = try beginTimes(of: .running, ink: NotchPalette.claudeCodeInk)

        // Every lit cell in a mark is anchored together, as it always was.
        #expect(codex.count == 9 * 4)
        #expect(claudeCode.count == codex.count)
        let codexPhase = try #require(codex.first)
        let claudePhase = try #require(claudeCode.first)
        #expect(codex.allSatisfy { $0 == codexPhase })
        #expect(claudeCode.allSatisfy { $0 == claudePhase })

        // Each mark is anchored to the clock as it read when the mark was
        // built: on the period grid, and within one period behind that
        // reading. This is what the default `beginTime` of 0 fails — 0 is on
        // every grid, but it is however long the process has been up behind
        // the clock, which is exactly the "phase records when it was built"
        // the fix removes.
        let period = try #require(NotchMatrixState.running.period)
        for (phase, builtAt) in [(codexPhase, builtCodexAt), (claudePhase, builtClaudeAt)] {
            #expect(offGrid(phase, period) < 1e-9)
            #expect(phase <= builtAt)
            #expect(builtAt - phase < period)
        }

        // So the two marks differ by whole periods, which is the same point of
        // the same curve. Before the fix this gap was the 120ms wait.
        #expect(offGrid(claudePhase - codexPhase, period) < 1e-9)

        // The anchor itself: the last whole-period boundary at or before now,
        // never ahead of it, never a full period behind. Both periods the
        // states use, because 1.2 is the one floating point rounds.
        for period in [1.0, 1.2] {
            let anchor = MatrixIndicatorView.phaseAnchor(for: period, now: 10.7)
            #expect(anchor <= 10.7)
            #expect(10.7 - anchor < period)
            #expect(offGrid(anchor, period) < 1e-9)
        }
    }

    /// One mark per connected product, in `AgentKind` order, never by urgency.
    @Test @MainActor
    func theMarksAreOnePerConnectedProductInAFixedOrder() throws {
        let running = MonitoredSession(
            agent: .claudeCode,
            threadID: "t", turnID: "u", projectName: "p", title: "t",
            preview: nil, status: .running, startedAt: nil
        )

        // Claude Code is busy and Codex is quiet: the busy one must NOT jump to
        // the front, or the marks swap under the eye reading them.
        let both = AgentSnapshotMerge.merge([
            makeAgentSnapshot(.codex, availability: .ready),
            makeAgentSnapshot(.claudeCode, availability: .ready, sessions: [running])
        ])
        #expect(both.presenceMarks.map(\.agent) == [.codex, .claudeCode])
        // Each matrix runs its own curve: Codex is quiet, Claude Code is running.
        #expect(both.presenceMarks.map(\.status) == [.connected, .running])

        // Only the second product connected: its mark takes the single slot
        // rather than leaving a gap where the first would have been.
        let claudeOnly = AgentSnapshotMerge.merge([
            makeAgentSnapshot(.codex, availability: .ready, presence: .closed),
            makeAgentSnapshot(.claudeCode, availability: .ready, sessions: [running])
        ])
        #expect(claudeOnly.presenceMarks.map(\.agent) == [.claudeCode])

        // Nothing connected: exactly one resting mark, never zero and never two.
        let nothing = AgentSnapshotMerge.merge([
            makeAgentSnapshot(.codex, availability: .ready, presence: .closed)
        ])
        #expect(nothing.presenceMarks.count == 1)
        let resting = try #require(nothing.presenceMarks.first)
        #expect(resting.isResting)
        #expect(resting.status == .disconnected)
    }

    /// One product's turn must not light the other product's mark.
    @Test @MainActor
    func aTurnOnlyLightsItsOwnProductsMark() {
        let codexTurn = MonitoredSession(
            agent: .codex,
            threadID: "t", turnID: "u", projectName: "p", title: "t",
            preview: nil, status: .approvalNeeded, startedAt: nil
        )
        let merged = AgentSnapshotMerge.merge([
            makeAgentSnapshot(.codex, availability: .ready, sessions: [codexTurn]),
            makeAgentSnapshot(.claudeCode, availability: .ready)
        ])

        #expect(merged.presenceMarks.map(\.status) == [.approvalNeeded, .connected])
        // The summary still speaks for the whole surface, and takes the urgent one.
        #expect(merged.status == .approvalNeeded)
    }

    /// The two form factors differ in whether the resting state is visible at all.
    ///
    /// A notched display already has a shape cut into the menu bar, so a grey
    /// mark beside it is a second shape carrying no information — the wing goes
    /// away entirely. A no-notch pill has nothing to hide behind: a control that
    /// vanishes from the menu bar takes its position with it and everything to
    /// its left slides over, so it keeps the mark and holds its place.
    @Test @MainActor
    func onlyTheNotchedFormDrawsNothingWhileResting() {
        let notched = makeDisplay(id: "notched", ordinal: 1, menuBarHeight: 38, hasNotch: true)
        let external = makeDisplay(id: "external", ordinal: 2, menuBarHeight: 24, hasNotch: false)
        let store = MonitorStore(displays: [notched, external], services: [])
        store.applyForTesting(
            makeAgentSnapshot(.codex, availability: .ready, presence: .closed)
        )
        #expect(store.isRestingOnly)

        #expect(store.geometry == .notched)
        #expect(!store.drawsCompactMarks)

        store.selectDisplay(id: external.id)
        #expect(store.geometry == .noNotch)
        #expect(store.drawsCompactMarks)

        // A notched panel resting with nothing connected is the cut-out and
        // nothing else -- no leading wing at all.
        let restingNotched = PanelMetrics.size(
            geometry: .notched,
            isExpanded: false,
            statusReadoutText: "Disconnected",
            trailing: .empty,
            centerOcclusionWidth: 200,
            compactHeight: 46,
            status: .disconnected,
            matrixCount: 1,
            drawsCompactMarks: false
        )
        #expect(restingNotched.width == 200)

        // Once something connects, the wing comes back.
        let connectedNotched = PanelMetrics.size(
            geometry: .notched,
            isExpanded: false,
            statusReadoutText: "Connected",
            trailing: .empty,
            centerOcclusionWidth: 200,
            compactHeight: 46,
            status: .connected,
            matrixCount: 1,
            drawsCompactMarks: true
        )
        #expect(connectedNotched.width > restingNotched.width)
    }

    /// Hiding the wings leaves the cut-out alone in every state, not only the
    /// resting one.
    ///
    /// `onlyTheNotchedFormDrawsNothingWhileResting` already pins this *shape* —
    /// what is added here is that a connected product with a turn running gets
    /// A turn that started since the last tick still draws a readout.
    ///
    /// **The tick is not the clock; it is a once-a-second sample of it.** A row
    /// whose start is later than the last sample is a turn that began between
    /// ticks, not an untimed one — and the difference decides which *view* the
    /// row draws, not merely what it says. Answering "not timed" swaps
    /// ``ElapsedReadout`` out for the untimed dot, and only a re-render puts it
    /// back; the once-a-second re-measure is gated on the readouts' width
    /// (`AGENTS.md` §7), and `0:09` → nothing → `0:00` never changes it. So the
    /// row lost its timer for the rest of the turn while the collapsed pill,
    /// whose own readout stayed mounted, went on counting. Measured on a
    /// Release build, 2026-08-24.
    @Test @MainActor
    func aTurnThatStartedSinceTheLastTickStillReadsAsTimed() {
        let clock = TestClock(now: Date(timeIntervalSince1970: 10_000))
        let store = MonitorStore(
            displays: [makeDisplay(id: "d", ordinal: 1, menuBarHeight: 24, hasNotch: false)],
            services: [],
            clock: clock
        )
        // Started half a second after the tick the store is holding.
        let justStarted = MonitoredSession(
            agent: .codex,
            threadID: "t", turnID: "u", projectName: "p", title: "t",
            preview: nil, status: .running,
            startedAt: clock.now().addingTimeInterval(0.5)
        )
        store.applyForTesting(
            makeAgentSnapshot(.codex, availability: .ready, sessions: [justStarted])
        )

        #expect(store.elapsedText(for: justStarted) == "0:00")
        #expect(store.elapsedStart(for: justStarted) == justStarted.startedAt)
        #expect(store.compactTimerText == "0:00")
        #expect(store.compactTimerStart == justStarted.startedAt)
        #expect(store.spokenElapsedText(for: justStarted) == "0 seconds")

        // A finished row is still untimed: this softens a stale tick, nothing else.
        let finished = MonitoredSession(
            agent: .codex,
            threadID: "t2", turnID: "u2", projectName: "p", title: "t",
            preview: nil, status: .completed,
            startedAt: clock.now().addingTimeInterval(-30)
        )
        #expect(store.elapsedText(for: finished) == nil)
        #expect(store.elapsedStart(for: finished) == nil)
    }

    /// it too, marks and timer alike, and that the body still lands exactly on
    /// the cut-out's own edges rather than merely near them.
    @Test @MainActor
    func hidingTheWingsLeavesTheNotchedPanelAsTheCutOutAlone() {
        let display = makeDisplay(
            id: "notched",
            ordinal: 1,
            menuBarHeight: 38,
            hasNotch: true
        )
        let store = MonitorStore(displays: [display], services: [])
        let running = MonitoredSession(
            agent: .codex,
            threadID: "t", turnID: "u", projectName: "p", title: "t",
            preview: nil, status: .running,
            startedAt: Date(timeIntervalSinceNow: -90)
        )
        store.applyForTesting(
            makeAgentSnapshot(.codex, availability: .ready, sessions: [running])
        )

        // Both wings are drawn to begin with: a mark leading the cut-out and a
        // timer trailing it.
        #expect(store.drawsCompactMarks)
        #expect(store.compactTimerText != nil)
        #expect(store.currentPanelSize.width > display.centerOcclusionWidth)

        store.hidesCompactWings = true

        #expect(store.hidesCompactSurface)
        #expect(!store.drawsCompactMarks)
        #expect(store.compactTimerText == nil)
        #expect(store.currentPanelSize.width == display.centerOcclusionWidth)
        #expect(store.currentPanelTrailingAnchor == display.centerOcclusionMaxX)

        // Expanded is untouched. The panel is the only way back into this
        // product, so the preference stops at the moment the pointer arrives.
        store.isExpanded = true
        #expect(store.drawsCompactMarks)
        #expect(store.currentPanelSize.width > display.centerOcclusionWidth)
    }

    /// The preference belongs to the user; whether it can be honoured belongs
    /// to the display.
    ///
    /// A no-notch pill has nothing to hide behind — hiding it would take its
    /// place in the menu bar with it and leave no shape to hover — so the
    /// switch is greyed there rather than the preference being cleared. Sending
    /// the component to an external monitor and back must not cost the setting.
    @Test @MainActor
    func onlyANotchedDisplayHonoursTheWingPreferenceAndTheOtherOneDoesNotClearIt() {
        let defaults = UserDefaults(suiteName: "wings-\(UUID().uuidString)")!
        let notched = makeDisplay(
            id: "notched",
            ordinal: 1,
            menuBarHeight: 38,
            hasNotch: true
        )
        let external = makeDisplay(
            id: "external",
            ordinal: 2,
            menuBarHeight: 24,
            hasNotch: false
        )
        let store = MonitorStore(
            displays: [notched, external],
            services: [],
            preferences: defaults
        )
        #expect(!store.hidesCompactWings)
        #expect(store.canHideCompactWings)

        store.hidesCompactWings = true
        #expect(store.hidesCompactSurface)
        // Remembered across launches, like the fold and the display itself.
        #expect(
            MonitorStore(displays: [notched], services: [], preferences: defaults)
                .hidesCompactWings
        )

        store.selectDisplay(id: external.id)
        #expect(!store.canHideCompactWings)
        #expect(!store.hidesCompactSurface)
        // The pill keeps its mark and its position, exactly as it does resting.
        #expect(store.drawsCompactMarks)
        // And the preference survived the display that could not honour it.
        #expect(store.hidesCompactWings)

        store.selectDisplay(id: notched.id)
        #expect(store.hidesCompactSurface)
    }

    /// A notch this app cannot place is a notch it cannot shrink onto.
    ///
    /// Giving up the wings means putting the collapsed body exactly on the
    /// hardware's own shape, and there is nothing else left on screen to place
    /// it by. A display reporting a notch but no gap between its auxiliary
    /// areas is already laid out as an *emulated* notch for that reason; the
    /// switch is greyed there for the same one, rather than being movable into
    /// a state that would draw a zero-width panel.
    @Test @MainActor
    func aNotchWithNoMeasurableGapCannotGiveUpItsWings() {
        let frame = NSRect(x: 0, y: 0, width: 1_920, height: 1_080)
        let menuBarHeight: CGFloat = 38
        // Both auxiliary areas present and non-empty -- so this reads as a
        // notched display -- but meeting in the middle, so the cut-out between
        // them measures zero.
        let unplaceable = DisplayOption(
            id: "notched-unplaceable",
            displayID: nil,
            ordinal: 1,
            name: "Display 1",
            frame: frame,
            visibleFrame: NSRect(
                x: frame.minX,
                y: frame.minY,
                width: frame.width,
                height: frame.height - menuBarHeight
            ),
            safeAreaInsets: NSEdgeInsets(
                top: menuBarHeight,
                left: 0,
                bottom: 0,
                right: 0
            ),
            auxiliaryTopLeftArea: NSRect(
                x: frame.minX,
                y: frame.maxY - menuBarHeight,
                width: frame.width / 2,
                height: menuBarHeight
            ),
            auxiliaryTopRightArea: NSRect(
                x: frame.midX,
                y: frame.maxY - menuBarHeight,
                width: frame.width / 2,
                height: menuBarHeight
            ),
            fallbackMenuBarHeight: menuBarHeight
        )
        #expect(unplaceable.geometry == .notched)
        #expect(unplaceable.centerOcclusionWidth == 0)

        let store = MonitorStore(displays: [unplaceable], services: [])
        #expect(!store.canHideCompactWings)

        // Even asked for outright, it does not take effect: the emulated pill
        // keeps its mark, because hiding it would leave nothing on the screen.
        store.hidesCompactWings = true
        #expect(!store.hidesCompactSurface)
        #expect(store.drawsCompactMarks)
        #expect(store.currentPanelSize.width > 0)
    }

    /// The outline is the user's answer to their own wallpaper, so it is
    /// remembered and it asks nothing of the display.
    ///
    /// The one form it stands down on is the collapsed surface that has given
    /// up its wings: there the body *is* the cut-out and the only lit part of
    /// the contour is the pair of shoulders, so an outline would draw two grey
    /// hooks on the one form whose point is that it carries no marks. Hovering
    /// drops a panel with an edge of its own, and the outline comes back with
    /// it.
    @Test @MainActor
    func theOutlineIsRememberedAndStandsDownOnlyForTheHiddenCompactSurface() {
        let defaults = UserDefaults(suiteName: "outline-\(UUID().uuidString)")!
        let notched = makeDisplay(
            id: "notched",
            ordinal: 1,
            menuBarHeight: 38,
            hasNotch: true
        )
        let external = makeDisplay(
            id: "external",
            ordinal: 2,
            menuBarHeight: 24,
            hasNotch: false
        )
        let store = MonitorStore(
            displays: [notched, external],
            services: [],
            preferences: defaults
        )
        #expect(!store.drawsSurfaceOutline)
        #expect(!store.showsSurfaceOutline)

        store.drawsSurfaceOutline = true
        #expect(store.showsSurfaceOutline)
        // Remembered across launches, like the fold and the wings.
        #expect(
            MonitorStore(displays: [notched], services: [], preferences: defaults)
                .drawsSurfaceOutline
        )

        // No display can withhold it: an emulated pill has an edge too, and it
        // is the form most likely to be lost against a dark wallpaper.
        store.selectDisplay(id: external.id)
        #expect(store.showsSurfaceOutline)
        store.selectDisplay(id: notched.id)

        // The two preferences do not fight. Collapsed onto the cut-out there is
        // no edge to trace; the panel that hover drops has one.
        store.hidesCompactWings = true
        #expect(store.hidesCompactSurface)
        #expect(!store.showsSurfaceOutline)
        store.isExpanded = true
        #expect(store.showsSurfaceOutline)
    }

    /// A second mark widens the notched wing by exactly one matrix and its gap.
    @Test @MainActor
    func aSecondMarkWidensTheNotchedWingByOneMatrix() {
        func width(markCount: Int) -> CGFloat {
            PanelMetrics.size(
                geometry: .notched,
                isExpanded: false,
                statusReadoutText: "Running",
                trailing: .empty,
                centerOcclusionWidth: 200,
                compactHeight: 46,
                status: .running,
                matrixCount: markCount,
                drawsCompactMarks: true
            ).width
        }
        let step = width(markCount: 2) - width(markCount: 1)
        #expect(
            abs(step - (PanelMetrics.statusMatrixSize + PanelMetrics.compactMatrixSpacing))
                <= 1
        )
        // The pair spacing lands on the matrix's own cell pitch so the gap reads
        // as a missing column rather than an arbitrary space.
        #expect(PanelMetrics.compactMatrixSpacing == 6)
    }

    /// Hovering with nothing connected widens the pill and drops no panel.
    @Test @MainActor
    func theRestingPillGrowsSidewaysRatherThanOpeningAnEmptyPanel() {
        let store = MonitorStore(services: [])
        store.applyForTesting(
            makeAgentSnapshot(.codex, availability: .ready, presence: .closed)
        )
        #expect(store.expandsToPillOnly)

        for geometry in DisplayGeometry.allCases {
            let occlusion: CGFloat = geometry == .notched ? 200 : 0
            let resting = PanelMetrics.size(
                geometry: geometry,
                isExpanded: false,
                statusReadoutText: "Disconnected",
                trailing: .empty,
                centerOcclusionWidth: occlusion,
                compactHeight: 46,
                status: .disconnected,
                matrixCount: 1,
                drawsCompactMarks: geometry == .noNotch
            )
            let hovered = PanelMetrics.size(
                geometry: geometry,
                isExpanded: true,
                statusReadoutText: "Disconnected",
                trailing: .empty,
                centerOcclusionWidth: occlusion,
                compactHeight: 46,
                status: .disconnected,
                matrixCount: 1,
                expandsToPillOnly: true
            )
            // Sideways only: it stays exactly one menu bar tall.
            #expect(hovered.height == 46)
            #expect(hovered.width > resting.width)
            // And it is nowhere near the full panel, which is what it is not opening.
            #expect(hovered.width < PanelMetrics.expandedBaselineWidth)
        }

        // Once a product connects, hovering opens the panel properly again.
        store.applyForTesting(makeAgentSnapshot(.codex, availability: .ready))
        #expect(!store.expandsToPillOnly)
    }

    /// The footer has exactly as many rules as the notch has marks.
    @Test @MainActor
    func theFooterDrawsOneRuleBlockPerConnectedProduct() throws {
        let store = MonitorStore(services: [])
        store.applyForTesting(
            AgentSnapshot(
                agent: .codex,
                availability: .ready,
                sessions: [],
                quota: QuotaSnapshot(remainingPercent: 72, resetsAt: nil, todayTokens: 1000),
                diagnostic: nil
            )
        )
        #expect(store.footerRules.map(\.agent) == [.codex])
        // Codex spans the full width because it has one window.
        #expect(try #require(store.footerRules[checked: 0]).windows.count == 1)
        // One window leaves room in the caption, so today's tokens stay inline.
        #expect(store.footerTodayText == nil)
        #expect(store.expandedFooterHeight == PanelMetrics.expandedFooterHeight)

        store.applyForTesting(
            AgentSnapshot(
                agent: .claudeCode,
                availability: .ready,
                sessions: [],
                quota: QuotaSnapshot(
                    windows: [
                        QuotaWindow(label: "5 h", remainingPercent: 59, resetsAt: nil),
                        QuotaWindow(label: "7 d", remainingPercent: 85, resetsAt: nil)
                    ],
                    todayTokens: 2000
                ),
                diagnostic: nil
            )
        )
        #expect(store.footerRules.map(\.agent) == [.codex, .claudeCode])
        // Claude Code is halved because it genuinely has two windows.
        #expect(try #require(store.footerRules[checked: 1]).windows.count == 2)
        // Four captions fill the line, so today's usage needs one of its own.
        let today = try? #require(store.footerTodayText)
        #expect(today?.contains("Codex") == true)
        #expect(today?.contains("Claude Code") == true)
        #expect(store.expandedFooterHeight == PanelMetrics.dualFooterHeight)
    }

    /// The footer says a fresh 5-hour window has not started, not that its
    /// reset is unavailable.
    ///
    /// The window's clock begins at the first request of the day, so a user who
    /// has not made one yet is looking at a full rule with nothing to count
    /// down to. The old caption blamed the app for that.
    @Test @MainActor
    func theFooterCallsAnUntouchedWindowNotStarted() throws {
        let store = MonitorStore(
            services: [],
            initialSnapshot: AgentSnapshot(
                agent: .claudeCode,
                availability: .ready,
                sessions: [],
                quota: QuotaSnapshot(
                    windows: [
                        QuotaWindow(label: "5 h", remainingPercent: 100, resetsAt: nil),
                        QuotaWindow(label: "7 d", remainingPercent: 85, resetsAt: nil)
                    ],
                    todayTokens: 0
                ),
                diagnostic: nil
            )
        )
        let windows = try #require(store.footerRules[checked: 0]).windows
        #expect(
            try #require(windows[checked: 0]).caption
                == "5 h · 100% left · Not started"
        )
        // The spent window is untouched by this: a percentage with no reset is
        // still how a wording change announces itself.
        #expect(
            try #require(windows[checked: 1]).caption
                == "7 d · 85% left · Reset unavailable"
        )
    }

    /// Folded, the panel is one height whatever is connected.
    ///
    /// That is the whole point of §5.4: unfolded the expanded panel is `326`,
    /// `340` or `370` depending on which products happen to be running, and
    /// folded it stops depending on that at all.
    @Test @MainActor
    func aFoldedFooterIsTheSameHeightForEveryShape() {
        func rules(_ shape: [(AgentKind, Int)]) -> [FooterRule] {
            shape.map { agent, windowCount in
                FooterRule(
                    agent: agent,
                    windows: (0..<windowCount).map { _ in
                        FooterWindow(fill: 0.5, caption: "c")
                    }
                )
            }
        }
        let codexAlone = rules([(.codex, 1)])
        let claudeAlone = rules([(.claudeCode, 2)])
        let both = rules([(.codex, 1), (.claudeCode, 2)])

        func panelHeight(_ shape: [FooterRule], folded: Bool) -> CGFloat {
            PanelMetrics.referenceCompactHeight
                + PanelMetrics.expandedContentHeight(
                    forSessionCount: 3,
                    footerHeight: PanelMetrics.footerHeight(
                        rules: shape, isFolded: folded
                    )
                )
        }

        // Unfolded: three shapes, three heights. 46 + 240 + footer.
        #expect(panelHeight(codexAlone, folded: false) == 326)
        #expect(panelHeight(claudeAlone, folded: false) == 340)
        #expect(panelHeight(both, folded: false) == 370)

        // Folded: one footer height, and the same panel every time.
        #expect(panelHeight(codexAlone, folded: true) == 314)
        #expect(panelHeight(claudeAlone, folded: true) == 314)
        #expect(panelHeight(both, folded: true) == 314)
        #expect(
            PanelMetrics.footerHeight(rules: both, isFolded: true)
                == PanelMetrics.foldedFooterHeight
        )

        // Nothing drawn is nothing to fold, so folding must not shrink it.
        #expect(
            PanelMetrics.footerHeight(rules: [], isFolded: true)
                == PanelMetrics.footerHeight(rules: [], isFolded: false)
        )
    }

    /// Today's line is the one thing folding never takes away.
    ///
    /// Codex alone is the trap: its tokens live inline in the rule's caption, so
    /// unfolded there is no totals line at all — and folded, that line has to
    /// come back or the number disappears with the rule.
    @Test @MainActor
    func foldingKeepsTodaysTokensInEveryShape() {
        let store = MonitorStore(services: [])
        store.applyForTesting(
            AgentSnapshot(
                agent: .codex,
                availability: .ready,
                sessions: [],
                quota: QuotaSnapshot(
                    remainingPercent: 72, resetsAt: nil, todayTokens: 310_100_000
                ),
                diagnostic: nil
            )
        )
        // Unfolded there is no totals line; the tokens ride the rule's caption.
        #expect(store.footerTodayText == nil)
        // Folded there has to be one, and with one product it does not name it.
        #expect(store.foldedTodayText == "310M today")
        #expect(!store.foldedTodayText.contains("Codex"))

        store.applyForTesting(
            AgentSnapshot(
                agent: .claudeCode,
                availability: .ready,
                sessions: [],
                quota: QuotaSnapshot(
                    windows: [
                        QuotaWindow(label: "5 h", remainingPercent: 40, resetsAt: nil),
                        QuotaWindow(label: "7 d", remainingPercent: 87, resetsAt: nil)
                    ],
                    todayTokens: 208_600_000
                ),
                diagnostic: nil
            )
        )
        // Two products, so both are named, folded or not — the line is the same.
        #expect(store.foldedTodayText == store.footerTodayText)
        #expect(store.foldedTodayText.contains("Codex"))
        #expect(store.foldedTodayText.contains("Claude Code"))
    }

    /// Folding has to move the panel, not just the footer inside it.
    ///
    /// The footer redraws itself from `isQuotaFolded`, but the height it gives
    /// up belongs to the window: without this the rules vanish and their space
    /// stays behind as an empty band under the last row.
    @Test @MainActor
    func foldingShrinksThePanelItself() {
        let display = makeDisplay(
            id: "notched",
            ordinal: 1,
            menuBarHeight: 38,
            hasNotch: true
        )
        let store = MonitorStore(
            displays: [display],
            services: [],
            initialSnapshot: AgentSnapshot(
                agent: .claudeCode,
                availability: .ready,
                sessions: [
                    MonitoredSession(
                        threadID: "thread",
                        turnID: "turn",
                        projectName: "Project",
                        title: "Session",
                        preview: nil,
                        status: .completed,
                        startedAt: nil
                    )
                ],
                quota: QuotaSnapshot(
                    windows: [
                        QuotaWindow(label: "5 h", remainingPercent: 40, resetsAt: nil),
                        QuotaWindow(label: "7 d", remainingPercent: 87, resetsAt: nil)
                    ],
                    todayTokens: 208_600_000
                ),
                diagnostic: nil
            )
        )
        store.isExpanded = true
        #expect(store.footerRules.map(\.agent) == [.claudeCode])

        let unfolded = store.currentPanelSize.height
        store.toggleQuotaFold()
        let folded = store.currentPanelSize.height

        #expect(
            unfolded - folded
                == PanelMetrics.claudeCodeOnlyFooterHeight
                    - PanelMetrics.foldedFooterHeight
        )
        #expect(folded < unfolded)
    }

    /// The fold is remembered, and starts showing the rules.
    @Test @MainActor
    func theFoldIsOneRememberedStateForTheWholeFooter() {
        let defaults = UserDefaults(suiteName: "fold-\(UUID().uuidString)")!
        let store = MonitorStore(services: [], preferences: defaults)
        #expect(!store.isQuotaFolded)

        store.toggleQuotaFold()
        #expect(store.isQuotaFolded)
        #expect(MonitorStore(services: [], preferences: defaults).isQuotaFolded)

        store.toggleQuotaFold()
        #expect(!MonitorStore(services: [], preferences: defaults).isQuotaFolded)

        // The control follows the rules, not the reading: an unavailable quota
        // still draws its track greyed, and that track is one a user may well
        // want folded away. It is only withheld when no rule is drawn at all,
        // which `aFoldedFooterIsTheSameHeightForEveryShape` covers by height.
        store.applyForTesting(makeAgentSnapshot(.codex, availability: .ready))
        #expect(store.showsQuotaFoldControl)
    }

    /// The panel grows for the second product's rules, and by exactly that much.
    @Test @MainActor
    func theDualProductPanelIsTallerByTheExtraFooterRules() {
        let single = PanelMetrics.expandedContentHeight(
            forSessionCount: 3,
            footerHeight: PanelMetrics.expandedFooterHeight
        )
        let dual = PanelMetrics.expandedContentHeight(
            forSessionCount: 3,
            footerHeight: PanelMetrics.dualFooterHeight
        )
        // 46 + 240 + 40 and 46 + 240 + 84, from dual-agent-design 5.1.
        #expect(PanelMetrics.referenceCompactHeight + single == 326)
        #expect(PanelMetrics.referenceCompactHeight + dual == 370)
        // Claude Code alone sits between them: two windows fill its caption
        // line, so today's usage still needs a line of its own.
        #expect(PanelMetrics.claudeCodeOnlyFooterHeight > PanelMetrics.expandedFooterHeight)
        #expect(PanelMetrics.claudeCodeOnlyFooterHeight < PanelMetrics.dualFooterHeight)
    }

    /// A row's gutter and its padding are one margin split in two.
    ///
    /// The block is inset `6` so the hover fill does not run into the panel
    /// edge, and the row pads the other `6` back, which puts its text on the
    /// same margin as the matrix in the header and the quota rules in the
    /// footer. Splitting it any other way is a visible change — the text stops
    /// lining up with everything else in the panel — so it fails here first.
    @Test @MainActor
    func aRowsTextLandsOnTheSameMarginAsTheRestOfThePanel() {
        #expect(
            PanelMetrics.sessionRowGutter + PanelMetrics.sessionRowPadding
                == PanelMetrics.expandedHorizontalPadding
        )
        #expect(PanelMetrics.sessionRowGutter == 6)

        // The block itself is wider than the panel's content box by the two
        // gutters it gives back: 520 - 6 - 6, against the header's 520 - 12 - 12.
        let block = PanelMetrics.expandedBaselineWidth
            - PanelMetrics.sessionRowGutter * 2
        let contentBox = PanelMetrics.expandedBaselineWidth
            - PanelMetrics.expandedHorizontalPadding * 2
        #expect(block == 508)
        #expect(contentBox == 496)
    }

    /// Rows say which product they are for as long as both products are connected.
    ///
    /// This used to be keyed to the rows themselves — attribution appeared only
    /// while two products each had one — and the mark then blinked out whenever
    /// one product happened to have nothing running, with both still open. What
    /// the user is telling apart is the pair of products, and that fact holds
    /// still for as long as the pair is connected.
    @Test @MainActor
    func rowsAreAttributedForAsLongAsBothProductsAreConnected() {
        let store = MonitorStore(services: [])
        func session(_ agent: AgentKind, _ id: String) -> MonitoredSession {
            MonitoredSession(
                agent: agent,
                threadID: id, turnID: "u", projectName: "p", title: "t",
                preview: nil, status: .running, startedAt: nil
            )
        }

        store.applyForTesting(
            makeAgentSnapshot(.codex, availability: .ready, sessions: [session(.codex, "a")])
        )
        #expect(!store.showsProductAttribution)

        // Connected but with nothing running: still two products to tell apart,
        // and the Codex rows on screen keep their mark rather than losing it
        // until Claude Code's next turn happens to start.
        store.applyForTesting(
            makeAgentSnapshot(.claudeCode, availability: .ready, sessions: [])
        )
        #expect(store.showsProductAttribution)

        store.applyForTesting(
            makeAgentSnapshot(
                .claudeCode,
                availability: .ready,
                sessions: [session(.claudeCode, "b")]
            )
        )
        #expect(store.showsProductAttribution)

        // Closed, so there is one product again and no second mark to explain.
        store.applyForTesting(
            makeAgentSnapshot(.claudeCode, availability: .ready, presence: .closed)
        )
        #expect(!store.showsProductAttribution)

        // The default is the only option that adds nothing to the panel.
        #expect(store.productAttribution == .nameAndColour)
        // And every option is reachable, because a preference the user cannot
        // find until a second product happens to be running is one they never find.
        #expect(ProductAttributionStyle.allCases.count == 4)
    }

    /// A closed product's rows still identify themselves while they are listed.
    ///
    /// Presence is the rule, but it is not the whole rule: a product can close
    /// with its finished rows still on screen, and a list that is visibly mixed
    /// has to say which row is whose no matter what presence now reports.
    @Test @MainActor
    func rowsLeftBehindByAClosedProductKeepTheirMark() {
        let store = MonitorStore(services: [])
        func session(_ agent: AgentKind, _ id: String) -> MonitoredSession {
            MonitoredSession(
                agent: agent,
                threadID: id, turnID: "u", projectName: "p", title: "t",
                preview: nil, status: .completed, startedAt: nil
            )
        }

        store.applyForTesting(
            makeAgentSnapshot(.codex, availability: .ready, sessions: [session(.codex, "a")])
        )
        store.applyForTesting(
            makeAgentSnapshot(
                .claudeCode,
                availability: .ready,
                sessions: [session(.claudeCode, "b")],
                presence: .closed
            )
        )

        #expect(store.connectedAgents == [.codex])
        #expect(store.showsProductAttribution)
    }

    /// `Colour bar` takes the product off the caption entirely.
    ///
    /// The other three all spend caption room — that is the cost the rail was
    /// added to avoid — so the split is: `nameAndColour` and `nameOnly` prefix
    /// the words, `badge` moves them into a block of their own, and `colourBar`
    /// leaves the caption as the bare project name. Getting this wrong prints
    /// the product twice, once as a word and once as a rail.
    @Test @MainActor
    func onlyTheTwoNamingStylesPutTheProductOnTheCaption() {
        #expect(ProductAttributionStyle.nameAndColour.namesProductInCaption)
        #expect(ProductAttributionStyle.nameOnly.namesProductInCaption)
        #expect(!ProductAttributionStyle.badge.namesProductInCaption)
        #expect(!ProductAttributionStyle.colourBar.namesProductInCaption)

        // Every option is offered by name, and the rail is last: it is the one
        // that is purely hue, so it is a choice rather than the default.
        #expect(
            ProductAttributionStyle.allCases.map(\.displayName)
                == ["Name and colour", "Name only", "Badge", "Colour bar"]
        )
    }

    /// The colour goes on the product name, and stops there.
    ///
    /// `Name and colour` is the only style that tints at all, and what it tints
    /// is the two words that say which product — not the Project after them.
    /// The Project is the row's own subject; painting it the product's colour
    /// said the same thing twice and left the caption without an ordinary grey
    /// to read as ordinary.
    @Test @MainActor
    func onlyTheProductNameTakesTheProductColour() {
        #expect(ProductAttributionStyle.nameAndColour.tintsProductName)
        #expect(!ProductAttributionStyle.nameOnly.tintsProductName)

        // The two that put nothing on the caption cannot tint it either — a
        // style that both hid the name and coloured it would colour the
        // Project alone, which is the mistake this pair of flags exists to
        // keep apart.
        for style in ProductAttributionStyle.allCases
        where !style.namesProductInCaption {
            #expect(!style.tintsProductName)
        }
    }

    /// The rail lands on the panel's own margin, not half of it.
    ///
    /// The stroke sits on the row block's leading edge, so the block's margin
    /// is the rail's position. At the row's ordinary `6` it stood half an inset
    /// inboard of everything it is read against — the status matrix above it
    /// and the quota rules below it, both on `12` — and a mark that is nearly
    /// but not quite on a line reads as a mistake. Drawn, the block takes the
    /// full `12`, and the padding behind the stroke is the rail's own `8`
    /// rather than the row's `6`: that gap is clearance between a `2pt` line
    /// and the words, not an inset from a panel edge.
    @Test @MainActor
    func theAttributionRailLandsOnThePanelsOwnMargin() {
        #expect(
            PanelMetrics.sessionRowRailGutter
                == PanelMetrics.expandedHorizontalPadding
        )
        #expect(PanelMetrics.sessionRowRailGutter == 12)
        #expect(PanelMetrics.sessionRowRailPadding == 8)
        #expect(PanelMetrics.sessionRowPadding == 6)
        #expect(PanelMetrics.sessionRowRailWidth < PanelMetrics.sessionRowRailGutter)
        #expect(PanelMetrics.sessionRowRailWidth == 2)
    }

    /// The rail is as tall as the text it marks, and no taller.
    ///
    /// From the top of the Project caption to the bottom of the last line —
    /// so it reads as that block's own leading edge. Half the row (`40`) was a
    /// shape rather than a measurement: it stopped short of the caption above
    /// and the preview below and marked the row's middle instead. A row with no
    /// preview is genuinely shorter, and the rail shortens with it rather than
    /// overhanging by `10` at each end.
    @Test @MainActor
    func theAttributionRailSpansTheRowsTextExactly() {
        let threeLines = PanelMetrics.sessionRowCaptionHeight
            + PanelMetrics.sessionRowLineSpacing
            + PanelMetrics.sessionRowTitleHeight
            + PanelMetrics.sessionRowLineSpacing
            + PanelMetrics.sessionRowPreviewHeight
        #expect(threeLines == 53)
        #expect(PanelMetrics.sessionRowRailHeight(hasPreview: true) == threeLines)
        #expect(PanelMetrics.sessionRowRailHeight(hasPreview: false) == 33)
        #expect(
            PanelMetrics.sessionRowRailHeight(hasPreview: true)
                < PanelMetrics.sessionRowHeight
        )
        // It is the row's text it spans, not the row: the block's own 12pt
        // corners stay clear at either end.
        #expect(
            PanelMetrics.sessionRowHeight - threeLines
                > PanelMetrics.sessionRowRailRadius * 2
        )
    }

    /// Only a drawn rail moves the row block; the picker alone does not.
    ///
    /// The wider margin is the rail's own room. Choosing `Colour bar` with one
    /// product connected draws no rail — attribution is keyed to there being
    /// two products to tell apart — so a row that took the wider margin then
    /// would have indented every row for a stroke that is not there.
    @Test @MainActor
    func theRowBlockOnlyGivesUpItsGutterWhileTheRailIsDrawn() {
        let store = MonitorStore(services: [])
        store.productAttribution = .colourBar

        store.applyForTesting(makeAgentSnapshot(.codex, availability: .ready))
        #expect(!store.showsSessionRowRail)
        #expect(store.sessionRowGutter == PanelMetrics.sessionRowGutter)
        #expect(store.sessionRowPadding == PanelMetrics.sessionRowPadding)
        // Unmarked, the two are still one margin split in two.
        #expect(
            store.sessionRowGutter + store.sessionRowPadding
                == PanelMetrics.expandedHorizontalPadding
        )

        store.applyForTesting(makeAgentSnapshot(.claudeCode, availability: .ready))
        #expect(store.showsSessionRowRail)
        #expect(store.sessionRowGutter == PanelMetrics.sessionRowRailGutter)
        #expect(store.sessionRowPadding == PanelMetrics.sessionRowRailPadding)

        // Two products and any other style: no rail, so no wider margin either.
        store.productAttribution = .nameAndColour
        #expect(!store.showsSessionRowRail)
        #expect(store.sessionRowGutter == PanelMetrics.sessionRowGutter)
        #expect(store.sessionRowPadding == PanelMetrics.sessionRowPadding)
    }

    /// Settings goes to the display the component is on, so the store has to be
    /// able to name that display as an `NSScreen` and not only as an option.
    ///
    /// Every attached screen, one after another, because the answer has to hold
    /// for whichever one the user picked — and by identity (`===`), because
    /// "the right screen" here means the object the window will be placed on,
    /// not another one that happens to describe the same rectangle.
    @Test @MainActor
    func theStoreNamesTheScreenTheComponentIsOn() {
        let screens = NSScreen.screens
        // Nothing to place a window on: a headless runner, and there is no
        // weaker claim left to make.
        guard !screens.isEmpty else { return }

        let store = MonitorStore(services: [])
        for screen in screens {
            store.selectDisplay(id: DisplayOption.identifier(for: screen))
            #expect(store.selectedScreen === screen)
        }
    }

    /// Where it lands, every time it opens: centred across the screen, high.
    @Test
    func theSettingsWindowLandsCentredAndAboveTheMiddle() {
        let visible = NSRect(x: 1512, y: 0, width: 2560, height: 1400)
        let size = NSSize(width: 580, height: 700)
        let origin = SettingsWindowPlacement.origin(for: size, on: visible)

        #expect(origin.x == visible.midX - size.width / 2)
        // A third of the leftover height above it — where macOS itself centres
        // a window, and above the true middle, which is where a window centred
        // on the arithmetic centre looks low.
        #expect(
            origin.y == visible.maxY - size.height - (visible.height - size.height) / 3
        )
        #expect(origin.y > visible.midY - size.height / 2)

        // Taller than the screen it is going to: the top is the part that has
        // to be reachable, because that is where the title bar is.
        let clamped = SettingsWindowPlacement.origin(
            for: NSSize(width: size.width, height: 1600),
            on: visible
        )
        #expect(clamped.y == visible.minY)
    }

    /// `Show in Finder` opens something in all three of its states.
    ///
    /// The button is drawn on rows whose file may not exist — a product whose
    /// switch has never been on has never had `hooks.json` or `settings.json`
    /// written — and `activateFileViewerSelecting` on a path with no file at
    /// the end of it does nothing at all, silently. So the fallback to the
    /// enclosing folder is the case this pins, not a nicety.
    @Test
    func showInFinderFallsBackToTheFolderWhenTheFileIsNotThereYet() throws {
        let manager = FileManager.default
        let root = manager.temporaryDirectory
            .appendingPathComponent(UUID().uuidString, isDirectory: true)
        defer { try? manager.removeItem(at: root) }
        try manager.createDirectory(at: root, withIntermediateDirectories: true)

        let file = root.appendingPathComponent("hooks.json")
        // Nothing written yet: the folder is there, the file is not, so the
        // button opens the folder rather than greying out.
        #expect(FinderRevealTarget.revealing(file) == .open(root))

        try Data("{}".utf8).write(to: file)
        // Written: the folder opens with the file picked out in it.
        #expect(FinderRevealTarget.revealing(file) == .select(file))

        // Neither — the product has never run on this machine — is the one
        // state with nowhere to go, and the only one that greys the button.
        let absent = root
            .appendingPathComponent("never-created", isDirectory: true)
            .appendingPathComponent("hooks.json")
        #expect(FinderRevealTarget.revealing(absent) == nil)
    }

    /// The button and the writer point at one file each, not two.
    ///
    /// Settings knows a product only by kind, so it resolves the file through
    /// ``HookIntegrationPaths`` rather than spelling either path again. This
    /// pins that the by-kind spelling lands on the same two files the live
    /// services are built over.
    @Test
    func settingsResolvesEachProductsHookFileByKind() {
        #expect(
            HookIntegrationPaths.live(for: .codex).hooksConfiguration
                == HookIntegrationPaths.live().hooksConfiguration
        )
        #expect(
            HookIntegrationPaths.live(for: .claudeCode).hooksConfiguration
                == HookIntegrationPaths.liveClaudeCode().hooksConfiguration
        )
        #expect(
            HookIntegrationPaths.live(for: .codex).hooksConfiguration.lastPathComponent
                == "hooks.json"
        )
        #expect(
            HookIntegrationPaths.live(for: .claudeCode).hooksConfiguration.lastPathComponent
                == "settings.json"
        )
    }

    /// A preference written before the rail existed still reads back.
    @Test @MainActor
    func anUnknownAttributionStyleFallsBackToTheDefault() {
        let defaults = UserDefaults(suiteName: "rail-\(UUID().uuidString)")!
        defaults.set("colourBar", forKey: "productAttribution")
        #expect(MonitorStore(services: [], preferences: defaults)
            .productAttribution == .colourBar)

        defaults.set("somethingWeRemoved", forKey: "productAttribution")
        #expect(MonitorStore(services: [], preferences: defaults)
