    @Test @MainActor
    func notchedCompactDropsItsTrailingWingUntilATurnIsTimed() {
        let occlusion: CGFloat = 200
        func size(trailingText: String?) -> CGSize {
            PanelMetrics.size(
                geometry: .notched,
                isExpanded: false,
                statusReadoutText: "Running",
                trailing: CompactTrailingReading(timerText: trailingText),
                centerOcclusionWidth: occlusion,
                compactHeight: 46
            )
        }

        // Idle: leading wing + the cut-out, and nothing to its right but the
        // step that keeps the shoulder off the cut-out's flare — an empty
        // trailing *wing* would render as a second, fake notch.
        let idle = size(trailingText: nil)
        let leading = PanelMetrics.compactLeadingWidth(
            statusReadoutText: "Running",
            showsStatusText: false
        ) + PanelMetrics.expandedNotchClearance
        let overshoot = PanelMetrics.winglessTrailingOvershoot(menuBarHeight: 46)
        #expect(abs(idle.width - (leading + occlusion + overshoot)) <= 1)

        #expect(size(trailingText: "1:23").width > idle.width)
    }

    /// The panel's black edge lands on the cut-out's, which is the one
    /// alignment a notched compact panel has to get right.
    ///
    /// This replaces an assertion on `compactHorizontalOffset`, which stated
    /// the same thing as a displacement from the display centre — equivalent
    /// only while the cut-out is centred and the width is not rounded, and
    /// blind to the shoulder the window carries outside the body either way.
    @Test @MainActor
    func notchedCompactBodyEndsWhereTheCutOutEnds() throws {
        let display = makeDisplay(
            id: "notched",
            ordinal: 1,
            menuBarHeight: 38,
            hasNotch: true
        )
        let store = MonitorStore(displays: [display])
        let occlusionMaxX = try #require(display.centerOcclusionMaxX)

        // The cut-out's own edge, held out by whatever trailing wing is drawn —
        // and nothing is drawn there until a turn is being timed. A surface
        // drawing nothing at all keeps that edge exactly; one that draws marks
        // steps a fraction past it (`aWinglessTrailingEdgeStepsClearOfTheCutOut`).
        #expect(
            PanelMetrics.compactTrailingWingWidth(
                trailing: .empty,
                menuBarHeight: store.compactHeight,
                drawsCompactMarks: false
            ) == 0
        )
        #expect(
            PanelMetrics.compactTrailingWingWidth(
                trailing: CompactTrailingReading(timerText: "1:23"),
                menuBarHeight: store.compactHeight,
                drawsCompactMarks: true
            )
                > PanelMetrics.compactTrailingWingWidth(
                    trailing: .empty,
                    menuBarHeight: store.compactHeight,
                    drawsCompactMarks: true
                )
        )
        #expect(
            store.currentPanelTrailingAnchor
                == occlusionMaxX + PanelMetrics.compactTrailingWingWidth(
                    trailing: store.compactTrailingReading,
                    menuBarHeight: store.compactHeight,
                    drawsCompactMarks: store.drawsCompactMarks
                )
        )

        let shoulder = store.surfaceShoulderRadius
        #expect(shoulder > 0)
        let frame = OverlayPanelLayout.frame(
            on: display.frame,
            panelSize: store.currentPanelSize,
            surfaceShoulder: shoulder,
            trailingAnchor: occlusionMaxX
        )

        // The window is the panel plus one shoulder on each side. `PanelContour`
        // draws its straight sides a radius inside the rect it is given, so a
        // window sized to the panel puts the black that far inside the cut-out.
        #expect(frame.width == store.currentPanelSize.width + shoulder * 2)
        #expect(frame.maxX - shoulder == occlusionMaxX)
        #expect(frame.minX + shoulder == occlusionMaxX - store.currentPanelSize.width)

        // Nothing to pin to when there is no notch, and nothing pinned stays
        // centred on the display.
        let external = makeDisplay(
            id: "external",
            ordinal: 2,
            menuBarHeight: 24,
            hasNotch: false
        )
        #expect(external.centerOcclusionMaxX == nil)
        let centred = OverlayPanelLayout.frame(
            on: external.frame,
            panelSize: CGSize(width: 168, height: 24),
            surfaceShoulder: shoulder,
            trailingAnchor: nil
        )
        #expect(centred.midX == external.frame.midX)
    }

    /// A wingless trailing edge steps just past the cut-out's *reported* edge,
    /// so the shoulder curving back up to the menu bar is not drawn behind the
    /// flare at the top of the notch. See
    /// `PanelMetrics.winglessTrailingOvershoot(menuBarHeight:)` for why the
    /// reported rectangle is not the shape the panel has to clear.
    @Test @MainActor
    func aWinglessTrailingEdgeStepsClearOfTheCutOut() {
        let bar: CGFloat = 38
        let overshoot = PanelMetrics.winglessTrailingOvershoot(menuBarHeight: bar)

        // Small enough to read as the panel continuing out of the notch rather
        // than as a ledge beside it: half the shoulder it is clearing.
        #expect(overshoot > 0)
        #expect(overshoot < PanelMetrics.surfaceShoulderRadius(menuBarHeight: bar))

        // Drawing marks with an empty trailing slot -- the one shape that takes
        // the step.
        #expect(
            PanelMetrics.compactTrailingWingWidth(
                trailing: .empty,
                menuBarHeight: bar,
                drawsCompactMarks: true
            ) == overshoot
        )

        // Drawing nothing at all: the body *is* the cut-out, and stepping past
        // its edge would hang a sliver of black off the side of the notch.
        #expect(
            PanelMetrics.compactTrailingWingWidth(
                trailing: .empty,
                menuBarHeight: bar,
                drawsCompactMarks: false
            ) == 0
        )

        // A wing with something in it is already far clear of the flare, so it
        // is unchanged: its content plus the clearance.
        let timed = CompactTrailingReading(timerText: "1:23")
        #expect(
            PanelMetrics.compactTrailingWingWidth(
                trailing: timed,
                menuBarHeight: bar,
                drawsCompactMarks: true
            ) == PanelMetrics.compactTrailingWidth(trailing: timed)
                + PanelMetrics.expandedNotchClearance
        )

        // A share of the menu bar height like the two radii, because what it
        // clears is hardware: it shrinks in points as the scaling coarsens.
        #expect(PanelMetrics.winglessTrailingOvershoot(menuBarHeight: 22) < overshoot)
        #expect(PanelMetrics.winglessTrailingOvershoot(menuBarHeight: 0) == 0)

        // The body takes the step into its own width, which is what keeps it on
        // the trailing side: the window and the anchor grow by the same amount,
        // so the leading edge -- and the marks measured from it -- stay put.
        let body = PanelMetrics.size(
            geometry: .notched,
            isExpanded: false,
            statusReadoutText: "Running",
            trailing: .empty,
            centerOcclusionWidth: 200,
            compactHeight: bar,
            status: .running,
            matrixCount: 1,
            drawsCompactMarks: true
        ).width
        let leading = PanelMetrics.compactLeadingWidth(
            statusReadoutText: "Running",
            showsStatusText: false
        ) + PanelMetrics.expandedNotchClearance
        #expect(body == ceil(leading + 200 + overshoot))
    }

    /// The compact panel measures itself from rendered text, so only the widths
    /// that are pure constants are pinned. The rest are asserted as the
    /// relationships that actually matter: an exact pixel copied from a font
    /// metric goes red on the next system update without anything being wrong.
    @Test @MainActor
    func compactGeometryComposesTheNotchWings() {
        func width(
            geometry: DisplayGeometry,
            trailingText: String?,
            compactHeight: CGFloat
        ) -> CGFloat {
            PanelMetrics.size(
                geometry: geometry,
                isExpanded: false,
                statusReadoutText: "Running",
                trailing: CompactTrailingReading(timerText: trailingText),
                centerOcclusionWidth: geometry == .notched ? 200 : 0,
                compactHeight: compactHeight
            ).width
        }

        // Leading wing plus the cut-out, plus the step that keeps the trailing
        // shoulder off the cut-out's flare. No text is measured on a notched
        // compact panel, so this width is exact -- and it is the one number a
        // Figma variant can be checked against directly. `12` padding + `16.6`
        // matrix + `8` clearance + the `200` cut-out is `236.6`, which was the
        // `237` this asserted before the step; the step is `46 / 16`, and the
        // sum ceils to `240`.
        let notchedIdle = width(geometry: .notched, trailingText: nil, compactHeight: 46)
        #expect(notchedIdle == 240)
        #expect(
            notchedIdle == ceil(
                236.6 + PanelMetrics.winglessTrailingOvershoot(menuBarHeight: 46)
            )
        )

        // Timing a turn replaces the step with the trailing wing, and adds
        // nothing but the trailing wing.
        let notchedTimed = width(geometry: .notched, trailingText: "1:23", compactHeight: 46)
        let trailingWing = PanelMetrics.compactTrailingWidth(
            trailing: CompactTrailingReading(timerText: "1:23")
        )
            + PanelMetrics.expandedNotchClearance
        #expect(
            abs(
                (notchedTimed - notchedIdle)
                    - (trailingWing
                        - PanelMetrics.winglessTrailingOvershoot(menuBarHeight: 46))
            ) <= 1
        )

        // Only the notched panel composes its width from content. A no-notch
        // one is fixed, so the same two cases must not move it at all.
        #expect(
            width(geometry: .noNotch, trailingText: nil, compactHeight: 24)
                == width(geometry: .noNotch, trailingText: "1:23", compactHeight: 24)
        )
    }

    /// The indicator is a fixed size derived from the label, not a share of the
    /// menu bar. It scaled with the bar while the 13pt label did not, so the two
    /// drifted apart between a 46pt and a 24pt bar.
    @Test @MainActor
    func statusMatrixIsAFixedSizeDerivedFromTheLabel() {
        // 92:72 indicator-to-text at loaders.wtf, applied to the 13pt label.
        #expect(abs(PanelMetrics.statusMatrixSize - 13 * (92.0 / 72.0)) < 0.02)
    }

    /// The cut-out is a fixed shape in millimetres, so its radii are fixed
    /// *shares* of its height and every point value moves with the display
    /// scaling that sets the menu bar height. Pinning either one is right at one
    /// scaling and too round at every other, so both are asserted as ratios.
    @Test
    func surfaceRadiiTrackTheMenuBarHeightLikeTheCutOutDoes() {
        // The four notch heights a MacBook reports across its scalings, from
        // More Space down to Larger Text.
        for menuBarHeight in [38.0, 32, 28, 22] as [CGFloat] {
            #expect(
                abs(
                    PanelMetrics.surfaceShoulderRadius(menuBarHeight: menuBarHeight)
                        - menuBarHeight / 8
                ) < 0.001
            )
            #expect(
                abs(
                    PanelMetrics.surfaceBottomCornerRadius(
                        menuBarHeight: menuBarHeight
                    ) - menuBarHeight / 4
                ) < 0.001
            )
        }

        // The default 185 × 32 cut-out, which is where the two radii were
        // measured: 4 up top and 8 below.
        #expect(PanelMetrics.surfaceShoulderRadius(menuBarHeight: 32) == 4)
        #expect(PanelMetrics.surfaceBottomCornerRadius(menuBarHeight: 32) == 8)
    }

    /// The lower corners are twice the upper ones. Drawing them equal — as one
    /// `10` did on every notched display — reads as a rounded rectangle parked
    /// under the bezel rather than as the notch carrying on sideways.
    @Test
    func theShoulderIsHalfTheLowerCorner() {
        for menuBarHeight in [38.0, 24, 19] as [CGFloat] {
            #expect(
                abs(
                    PanelMetrics.surfaceBottomCornerRadius(
                        menuBarHeight: menuBarHeight
                    ) - PanelMetrics.surfaceShoulderRadius(
                        menuBarHeight: menuBarHeight
                    ) * 2
                ) < 0.001
            )
        }
    }

    @Test
    func surfaceRadiiNeverGoNegative() {
        #expect(PanelMetrics.surfaceShoulderRadius(menuBarHeight: -10) == 0)
        #expect(PanelMetrics.surfaceBottomCornerRadius(menuBarHeight: -10) == 0)
    }

