    /// Dismissing the same row twice changes nothing the second time.
    ///
    /// A secondary press is easy to repeat, and the row is gone from the panel
    /// by then anyway -- what this pins is that the second call reports it did
    /// nothing rather than reporting a fresh dismissal.
    @Test @MainActor
    func dismissingARowTwiceIsNotASecondDismissal() {
        let finished = MonitoredSession(
            threadID: "thread",
            turnID: "turn",
            projectName: "Chats",
            title: "Finished turn",
            preview: nil,
            status: .completed,
            startedAt: Date()
        )
        let store = MonitorStore(
            initialSnapshot: AgentSnapshot(
                availability: .ready,
                sessions: [finished],
                quota: .unavailable,
                diagnostic: nil
            )
        )

        #expect(store.dismiss(finished))
        #expect(!store.dismiss(finished))
        #expect(store.sessions.isEmpty)
    }

    /// The row's catcher takes the secondary press and nothing else.
    ///
    /// It covers the whole row, so every event it claims is one the button
    /// underneath never sees. Claiming a primary press would silently cost the
    /// list its navigation -- clicking a finished row would dismiss it instead
    /// of opening it -- and claiming a movement would do it for hover too.
    @Test @MainActor
    func theSecondaryClickCatcherClaimsOnlyTheSecondaryPress() {
        let claimed: [NSEvent.EventType] = [.rightMouseDown, .rightMouseUp]
        let passedThrough: [NSEvent.EventType] = [
            .leftMouseDown,
            .leftMouseUp,
            .leftMouseDragged,
            .mouseMoved,
            .mouseEntered,
            .mouseExited,
            .otherMouseDown,
            .scrollWheel,
            .keyDown
        ]

        for eventType in claimed {
            #expect(SecondaryClickView.claims(eventType))
        }
        for eventType in passedThrough {
            #expect(!SecondaryClickView.claims(eventType))
        }
        // AppKit also asks about geometry with no event in flight at all.
        #expect(!SecondaryClickView.claims(nil))
        #expect(SecondaryClickView().hitTest(.zero) == nil)
    }

    /// SwiftUI puts the catcher over the whole row, and the press it takes
    /// calls through.
    ///
    /// ``theSecondaryClickCatcherClaimsOnlyTheSecondaryPress()`` pins what the
    /// view answers when AppKit asks. This pins the other half: that there is a
    /// real view for AppKit to ask, covering the area the row occupies rather
    /// than collapsed to nothing by the overlay. Dispatching a synthetic mouse
    /// event to check the two halves together was tried and rejected -- it
    /// takes the test host down with it, which fails a dozen unrelated tests
    /// running beside it.
    @Test @MainActor
    func theSecondaryClickCatcherCoversTheRowAndCallsThrough() {
        final class Count { var value = 0 }
        let pressed = Count()
        let rowSize = CGSize(width: 120, height: PanelMetrics.sessionRowHeight)

        let hosting = NSHostingView(
            rootView: Color.clear
                .frame(width: rowSize.width, height: rowSize.height)
                .overlay { SecondaryClickCatcher { pressed.value += 1 } }
        )
        hosting.frame = NSRect(origin: .zero, size: rowSize)
        hosting.layoutSubtreeIfNeeded()

        func catchers(in view: NSView) -> [SecondaryClickView] {
            (view as? SecondaryClickView).map { [$0] } ?? view.subviews.flatMap(catchers(in:))
        }
        let catcher = catchers(in: hosting).first
        #expect(catcher != nil)
        #expect(catcher?.frame.size == rowSize)

        catcher?.rightMouseDown(
            with: NSEvent.mouseEvent(
                with: .rightMouseDown,
                location: .zero,
                modifierFlags: [],
                timestamp: 0,
                windowNumber: 0,
                context: nil,
                eventNumber: 0,
                clickCount: 1,
                pressure: 1
            )!
        )
        #expect(pressed.value == 1)
    }

    /// Recheck must report what is true now, not what was true before.
    ///
    /// It used to call a refresh that returned immediately whenever an
    /// automatic one happened to be in flight, so the button finished at once
    /// and handed back the status it already had (CR-008).
    @Test @MainActor
    func recheckWaitsForASnapshotThatAccountsForItOwnRequest() async throws {
        let service = GatedMonitoringStub()
        await service.setHoldsSnapshots(true)
        await service.setStatus(.reviewRequired)

        let store = MonitorStore(
            services: [service],
            initialSnapshot: AgentSnapshot(
                availability: .connecting,
                sessions: [],
                quota: .unavailable,
                diagnostic: nil,
                setupStatus: .notInstalled
            )
        )

        // Wait until the automatic refresh is genuinely in flight and stuck.
        for _ in 0 ..< 200 where await service.snapshotCount() < 1 {
            try await Task.sleep(nanoseconds: 5_000_000)
        }
        #expect(await service.snapshotCount() == 1)

        // The world changes while that refresh is parked.
        await service.setStatus(.active)

        // The user presses Recheck now.
        let recheck = Task { await store.recheckIntegrationAndWait() }
        try await Task.sleep(nanoseconds: 50_000_000)

        await service.setHoldsSnapshots(false)
        await service.releaseHeldSnapshots()

        let reported = await recheck.value
        #expect(
            reported == .active,
            "Recheck reported \(reported); it returned before a fresh read"
        )
        #expect(await service.snapshotCount() >= 2)
        store.stopMonitoring()
    }

    /// A watcher signal arriving mid-refresh must still produce a refresh.
    @Test @MainActor
    func aChangeSignalDuringARefreshIsServedRatherThanDropped() async throws {
        let service = GatedMonitoringStub()
        await service.setHoldsSnapshots(true)

        let store = MonitorStore(
            services: [service],
            initialSnapshot: AgentSnapshot(
                availability: .connecting,
                sessions: [],
                quota: .unavailable,
                diagnostic: nil,
                setupStatus: .notInstalled
            )
        )
        for _ in 0 ..< 200 where await service.snapshotCount() < 1 {
            try await Task.sleep(nanoseconds: 5_000_000)
        }

        // Three signals land while the first read is stuck. They collapse into
        // one follow-up -- coalesced, but not lost.
        store.refreshNow()
        store.refreshNow()
        store.refreshNow()

        await service.setHoldsSnapshots(false)
        await service.releaseHeldSnapshots()

        for _ in 0 ..< 200 where await service.snapshotCount() < 2 {
            try await Task.sleep(nanoseconds: 5_000_000)
        }
        #expect(
            await service.snapshotCount() >= 2,
            "a signal that arrived during a refresh was dropped"
        )
        store.stopMonitoring()
    }

    /// Flipping the switch faster than the work completes must still end where
    /// the user left it, and must not run two changes at once.
    @Test @MainActor
    func rapidIntegrationTogglesConvergeOnTheLastRequestedState() async throws {
        let service = GatedMonitoringStub()
        await service.setStatus(.notInstalled)
        let store = MonitorStore(
            services: [service],
            initialSnapshot: AgentSnapshot(
                availability: .setupRequired,
                sessions: [],
                quota: .unavailable,
                diagnostic: nil,
                setupStatus: .notInstalled
            )
        )

        store.setIntegrationEnabled(true)
        store.setIntegrationEnabled(false)
        let settled = await store.setIntegrationEnabledAndWait(true)

        #expect(settled)
        #expect(store.integrationSwitchIsOn, "the last flip must decide")
        #expect(store.hookSetupStatus.isIntegrationEnabled)
        #expect(await service.installCount() >= 1)
        #expect(
            await service.observedOverlappingIntegrationChange == false,
            "install and remove overlapped"
        )
        store.stopMonitoring()
    }

