    @Test
    func theStoreSignalsWhatIsDrawnAndNothingElse() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }

        let repository = HookEventRepository(paths: paths)
        let moment = Date().timeIntervalSince1970

        // A turn opening changes the row, so the panel is asked to redraw --
        // and it is asked directly, with no directory to watch and no 100 ms
        // debounce in front of it.
        #expect(
            await receivesChange(repository.changeEvents()) {
                deliverHook([
                    "received_at": moment,
                    "hook_event_name": "UserPromptSubmit",
                    "session_id": "thread-watch",
                    "turn_id": "turn-watch"
                ], to: repository)
            }
        )
        _ = await repository.drainDeliveredEvents()

        // A tool call *closing* draws nothing different and wakes nobody. This
        // is what replaced the debounce, and it is still the rule for every
        // event that only moves state no row reads.
        let quiet = await receivesChange(
            repository.changeEvents(),
            within: .milliseconds(400)
        ) {
            deliverHook([
                "received_at": moment + 1,
                "hook_event_name": "PostToolUse",
                "session_id": "thread-watch",
                "turn_id": "turn-watch",
                "tool_name": "Bash",
                "tool_use_id": "bash-0"
            ], to: repository)
        }
        #expect(!quiet)
        #expect(await repository.observedState().turns.first?.status == .running)

        // A tool call *opening* is the exception, and only on Codex. Nothing
        // this store holds moves -- the status stays Running and no field of
        // the projection changes -- but the row's third line is Codex's live
        // progress, read from the App Server against this turn, and this is the
        // moment it moves: Codex prints its commentary and then calls the tool.
        // Before this the row showed the user's own prompt for the whole turn.
        #expect(
            await receivesChange(repository.changeEvents()) {
                deliverHook([
                    "received_at": moment + 2,
                    "hook_event_name": "PreToolUse",
                    "session_id": "thread-watch",
                    "turn_id": "turn-watch",
                    "tool_name": "Bash",
                    "tool_use_id": "bash-1"
                ], to: repository)
            }
        )
        #expect(await repository.observedState().turns.first?.status == .running)

        // The turn ending does change the row.
        #expect(
            await receivesChange(repository.changeEvents()) {
                deliverHook([
                    "received_at": moment + 5,
                    "hook_event_name": "Stop",
                    "session_id": "thread-watch",
                    "turn_id": "turn-watch"
                ], to: repository)
            }
        )
    }

    @Test
    func claudeCodeToolCallsStayOffTheChangeStream() async throws {
        // The same events on the other product. Claude Code's row text arrives
        // here as `MessageDisplay` deltas, so the fold raises its own edge when
        // the line moves -- waking on its tool calls as well would be a second
        // wake for text that has already been reported, and a tool-heavy turn
        // is where that costs the most.
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }

        let repository = HookEventRepository(
            paths: paths,
            vocabulary: ClaudeCodeHookVocabulary()
        )
        let moment = Date().timeIntervalSince1970
        deliverHook([
            "received_at": moment,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "session-quiet",
            "prompt_id": "turn-quiet"
        ], to: repository)
        _ = await repository.drainDeliveredEvents()

        let quiet = await receivesChange(
            repository.changeEvents(),
            within: .milliseconds(400)
        ) {
            for (index, name) in ["PreToolUse", "PostToolUse"].enumerated() {
                deliverHook([
                    "received_at": moment + 1 + Double(index),
                    "hook_event_name": name,
                    "session_id": "session-quiet",
                    "prompt_id": "turn-quiet",
                    "tool_name": "Bash",
                    "tool_use_id": "bash-1"
                ], to: repository)
            }
        }
        #expect(!quiet)
        #expect(await repository.observedState().turns.first?.status == .running)
    }

    @Test @MainActor
    func readingSetupStatusNeverConsumesWhatTheRefreshIsOwed() async throws {
        // hookSetupStatus used to consume events, so a refresh drained the
        // queue twice and whatever the second call swallowed surfaced a cycle
        // late. It reads the store now, and reading must not take delivery.
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let installer = CodexHookRegistrar(paths: paths)
        try await installer.install()
        let repository = HookEventRepository(paths: paths)
        deliverHook([
            "received_at": Date().timeIntervalSince1970,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-intact",
            "turn_id": "turn-intact"
        ], to: repository)

        let service = LiveCodexMonitorService(
            client: CodexAppServerStub(
                listedThreads: [],
                loadedListResults: [],
                readableThreads: [codexRootThread(id: "thread-intact")]
            ),
            hookEvents: repository,
            hookRegistrar: installer,
            desktopProcessIdentifierProvider: { 4_242 }
        )

        // Querying health repeatedly must leave the refresh's own answer alone.
        for _ in 0 ..< 3 {
            _ = await service.hookSetupStatus()
        }
        #expect(await repository.observedState().hasObservedLiveEvent)

        // The snapshot path is the single consumer, and it still sees the Turn
        // as one that arrived since it last looked.
        let snapshot = await snapshotWithSessions(from: service)
        #expect(snapshot.sessions.first?.threadID == "thread-intact")
        #expect(snapshot.setupStatus == .active)
        await service.disconnect()
    }

    /// Registration health is recomputed when it can change, not on a cadence.
    ///
    /// It used to be a cached scan of three files behind a 60-second
    /// revalidation window, which meant an outside edit was invisible for up to
    /// a minute and the app paid for the question on a timer. There are two
    /// moments it can change now and the reading is dropped on both: this app
    /// writing the file, and the user asking for a recheck. The third -- the
    /// file changing underneath us -- is an FSEvents edge the registrar
    /// subscribes to itself.
    @Test @MainActor
    func registrationHealthIsRecomputedWhenItCanChangeRatherThanOnACadence() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let registrar = CodexHookRegistrar(paths: paths)
        try await registrar.install()
        #expect(await registrar.registration() == .complete)

        // Something outside this app removes a managed definition.
        var configuration = try #require(
            JSONSerialization.jsonObject(
                with: try Data(contentsOf: paths.hooksConfiguration)
            ) as? [String: Any]
        )
        var hooks = try #require(configuration["hooks"] as? [String: Any])
        hooks.removeValue(forKey: "Stop")
        configuration["hooks"] = hooks
        try JSONSerialization.data(withJSONObject: configuration)
            .write(to: paths.hooksConfiguration)

        // The recheck the user can ask for reads the file again, and reports
        // the damage as something to repair rather than as nothing installed --
        // the rest of the registration is still ours.
        await registrar.invalidateRegistration()
        #expect(await registrar.registration() == .mismatched)

        // Repairing it writes the file, which drops the reading by itself.
        try await registrar.install()
        #expect(await registrar.registration() == .complete)
    }

    /// The *first* reading after an outside edit is the edited one.
    ///
    /// The edge used to be delivered to two independent subscribers -- this
    /// actor dropping its cached reading, and the refresh that asks it the
    /// question -- with nothing ordering them. Whichever `Task` the scheduler
    /// resumed first decided which answer the user got, and a refresh that won
    /// cached the reading from before the edit with no second edge coming to
    /// correct it (CR-028).
    ///
    /// This is not a reproduction of that race -- a race cannot be lost on
    /// purpose, and against the old shape this test passed 50 runs out of 50,
    /// because the invalidating subscriber usually got there first. What it
    /// pins is the invariant that replaced the race: the first answer after the
    /// edge is the edited one by construction rather than by scheduling, and
    /// asserting eventual convergence instead would have said nothing at all.
    /// Defeat the change-count comparison and this fails every time.
    @Test @MainActor
    func theFirstRegistrationReadingAfterAnOutsideEditIsTheEditedOne() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let registrar = CodexHookRegistrar(paths: paths)
        try await registrar.install()
        #expect(await registrar.registration() == .complete)

        var configuration = try #require(
            JSONSerialization.jsonObject(
                with: try Data(contentsOf: paths.hooksConfiguration)
            ) as? [String: Any]
        )
        var hooks = try #require(configuration["hooks"] as? [String: Any])
        hooks.removeValue(forKey: "Stop")
        configuration["hooks"] = hooks
        let damaged = try JSONSerialization.data(withJSONObject: configuration)
        let hooksConfiguration = paths.hooksConfiguration

        // Something outside this app removes a managed definition, and keeps
        // removing it until the watcher reports the edit -- an in-place write,
        // so the file the registrar is watching is the file that changed.
        let observed = await receivesChange(registrar.changeEvents()) {
            try damaged.write(to: hooksConfiguration)
        }
        #expect(observed)

        // No `invalidateRegistration()` in between: the edge is the whole of
        // what is under test here.
        #expect(await registrar.registration() == .mismatched)
    }

    /// A reading taken while nothing was watching does not outlive the attach.
    ///
    /// On a first run `hooks.json` does not exist, so the watcher cannot attach
    /// and no edge will ever report the file appearing. The reading taken then
    /// -- `absent` -- was cached against nothing and would have survived
    /// somebody else creating the file, because the only thing that dropped it
    /// was an edge that could not be sent.
    @Test @MainActor
    func aReadingTakenBeforeTheWatcherCouldAttachIsNotKept() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let registrar = CodexHookRegistrar(paths: paths)
        #expect(await registrar.registration() == .absent)

        // Somebody else writes the file the watcher was waiting for.
        try await CodexHookRegistrar(paths: paths).install()

        #expect(await registrar.registration() == .complete)
    }

    @Test @MainActor
    func backgroundQuotaReadPublishesWithoutWaitingForADeadline() async throws {
        // Quota is read in the background, so it lands after the snapshot that
        // started it was already published. Nothing else was due for ten
        // seconds, so without its own trigger the ring stayed blank that long.
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let installer = CodexHookRegistrar(paths: paths)
        try await installer.install()

        let clock = TestClock()
        let timing = MonitorTiming.standard
        let client = CodexAppServerStub(
            listedThreads: [.object([
                "id": .string("thread-quota"),
                "ephemeral": .bool(false),
                "threadSource": .string("user")
            ])],
            loadedListResults: []
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: HookEventRepository(
                paths: paths,
                clock: clock,
                timing: timing
            ),
            hookRegistrar: installer,
            clock: clock,
            timing: timing
        )

        let triggers = service.stateChangeEvents
        let observer = Task {
            for await _ in triggers {
                return true
            }
            return false
        }

        let first = await service.fetchSnapshot()
        #expect(first.quota.remainingPercent == nil)

        // The store would otherwise be asleep. With no Hook observation nothing
        // in this state books a wake-up for the membership set at all
        // (CR-Fable-023), and every deadline that can be booked here is an
        // order of magnitude further out than the read itself takes. The
        // trigger below is the only thing that puts the ring on screen.
        if let deadline = await service.nextRefreshDeadline() {
            #expect(deadline.timeIntervalSince(clock.now()) >= 5)
        }

        let signalled = await withTaskGroup(of: Bool.self) { group in
            group.addTask { await observer.value }
            group.addTask {
                try? await Task.sleep(nanoseconds: 3_000_000_000)
                return false
            }
            let result = await group.next() ?? false
            group.cancelAll()
            return result
        }
        observer.cancel()
        #expect(signalled)

        let second = await service.fetchSnapshot()
        #expect(second.quota.remainingPercent == 70)
        await service.disconnect()
    }

    @Test @MainActor
    func theQuotaReadIsParkedWhileThereIsNoScreen() async throws {
        // The figures this buys are drawn in a footer the user reaches by
        // hovering the notch, so a locked screen means nobody can look at them.
        // Ungated, an idle machine issued three App Server requests a minute
        // all night -- and the branch below is the cheap one, reached with
        // Codex Desktop shut and no Hook observation at all.
        //
        // Both halves are asserted, because only one of them saves anything on
        // its own. The scheduler declining to read is what stops the requests;
        // `nextRefreshDeadline` dropping the entry is what stops the store
        // waking to be declined, which would otherwise be a deadline in the
        // past that no refresh could clear -- the busy-wait shape of
        // CR-Fable-050, one source further along.
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let installer = CodexHookRegistrar(paths: paths)
        try await installer.install()

        let clock = TestClock()
        let timing = MonitorTiming.standard
        let screen = StubScreenAvailability()
        let client = CodexAppServerStub(
            listedThreads: [],
            loadedListResults: []
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: HookEventRepository(
                paths: paths,
                clock: clock,
                timing: timing
            ),
            hookRegistrar: installer,
            screenAvailability: screen,
            clock: clock,
            timing: timing
        )

        // With a screen, the reading happens as it always did.
        _ = await service.fetchSnapshot()
        #expect(await holds {
            await client.requestCount(method: "account/rateLimits/read") == 1
        })
        #expect(await client.requestCount(method: "account/usage/read") == 1)
        #expect(await client.requestCount(method: "account/read") == 1)

        // Long enough that every window here is stale, so a refresh that still
        // reads would read now.
        screen.available = false
        await clock.advance(by: timing.quotaRefreshInterval + 1)

        _ = await service.fetchSnapshot()
        await clock.settle()
        #expect(await client.requestCount(method: "account/rateLimits/read") == 1)
        #expect(await client.requestCount(method: "account/usage/read") == 1)
        #expect(await client.requestCount(method: "account/read") == 1)

        // And nothing is booked to wake for the read that was just declined. A
        // deadline already in the past is the assertion that matters: the store
        // wakes at it, refreshes, and finds it exactly where it was.
        let parked = await service.nextRefreshDeadline()
        #expect(parked.map { $0 > clock.now() } ?? true)

        // The screen coming back is an edge `stateChangeEvents` already
        // carries, and the refresh it triggers takes the reading -- so the
        // figure the user looks at is at most one wake old, never a whole
        // locked night.
        screen.available = true
        _ = await service.fetchSnapshot()
        #expect(await holds {
            await client.requestCount(method: "account/rateLimits/read") == 2
        })
        #expect(await client.requestCount(method: "account/usage/read") == 2)
        #expect(await service.nextRefreshDeadline() != nil)
        await service.disconnect()
    }

    @Test @MainActor
    func refreshSleepsUntilTheNextDeadlineRatherThanACadence() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let installer = CodexHookRegistrar(paths: paths)
        let clock = TestClock()
        let timing = MonitorTiming.standard
        let repository = HookEventRepository(
            paths: paths,
            clock: clock,
            timing: timing
        )
        try await installer.install()
        try JSONSerialization.data(withJSONObject: [
            "received_at": Date().timeIntervalSince1970,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-deadline",
            "turn_id": "turn-deadline"
        ]).deliver(to: repository)

        let client = CodexAppServerStub(
            listedThreads: [.object([
                "id": .string("thread-deadline"),
                "ephemeral": .bool(false),
                "threadSource": .string("user"),
                "name": .string("Deadline")
            ])],
            loadedListResults: []
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            clock: clock,
            timing: timing,
            desktopProcessIdentifierProvider: { 4_242 }
        )

        // Nothing has been read yet, so nothing is scheduled: a quiet monitor
        // falls through to the heartbeat instead of sampling.
        #expect(await service.nextRefreshDeadline() == nil)

        _ = await service.fetchSnapshot()
        await waitForThreadReads(client, atLeast: 1)

        // Once metadata is cached the next wake-up is its staleness boundary --
        // sooner than the membership window, and far sooner than the heartbeat.
        let deadline = try #require(await service.nextRefreshDeadline())
        let untilDeadline = deadline.timeIntervalSince(clock.now())
        #expect(untilDeadline <= timing.threadMetadataRefreshInterval)
        #expect(untilDeadline < timing.heartbeatInterval)
        await service.disconnect()
    }

    @Test @MainActor
    func notchLabelDrawsGlyphsAndSweepsThroughCoreAnimation() throws {
        // The notch label is layer-backed so its sweep costs no per-frame view
        // work. That trade is only worth anything if it still draws text: the
        // failure modes are a blank label, or an unmasked band painting a solid
        // bar across the notch. Neither is visible from a unit test directly,
        // but both are visible in the rasterised glyphs and the mask.
        let font = NSFont.systemFont(ofSize: 13, weight: .light)
        let text = "Approval needed"
        let view = SweepingLabelView()
        view.apply(text: text, font: font, isSweeping: true, reduceMotion: false)

        // The same metrics PanelMetrics reserves compact width with, so the
        // label cannot be wider than the panel drawn for it.
        let measured = (text as NSString).size(withAttributes: [.font: font])
        #expect(view.intrinsicContentSize.width == ceil(measured.width))

        view.frame = NSRect(origin: .zero, size: view.intrinsicContentSize)
        view.layout()

        // Named rather than indexed: the reading on its way out is drawn above
        // both copies, and asserting on positions makes adding it look like a
        // regression. The order still matters and is asserted as an order.
        let sublayers = try #require(view.layer?.sublayers)
        #expect(sublayers.count == 3)
        let glyphs = try Self.labelLayer(named: SweepingLabelView.baseLayerName, in: view)
        let highlight = try Self.labelLayer(
            named: SweepingLabelView.highlightLayerName,
            in: view
        )
        let outgoing = try Self.labelLayer(
            named: SweepingLabelView.outgoingLayerName,
            in: view
        )
        #expect(sublayers.firstIndex(of: glyphs)! < sublayers.firstIndex(of: highlight)!)
        #expect(sublayers.firstIndex(of: highlight)! < sublayers.firstIndex(of: outgoing)!)

        // Nothing has been replaced yet, so nothing is mid-hand-over.
        #expect(outgoing.contents == nil)
        #expect(outgoing.opacity == 0)

        // The glyphs are framed to their own raster and never to the view, so a
        // frame the layout is still animating cannot stretch them.
        #expect(glyphs.frame.width == ceil(measured.width))

        let contents = try #require(glyphs.contents)
        let image = unsafeDowncast(contents as AnyObject, to: CGImage.self)
        #expect(image.width >= Int(measured.width))

        // Text, not a filled rectangle: a solid band would have no transparent
        // pixels, and a label that failed to draw would have no opaque ones.
        let alphas = try Self.alphaExtremes(of: image)
        #expect(alphas.minimum == 0)
        #expect(alphas.maximum > 0.5)

        // The highlight rides a mask that Core Animation drives.
        #expect(!highlight.isHidden)
        let mask = try #require(highlight.mask)
        #expect(mask.animation(forKey: "notch.searchlight") != nil)

        view.apply(text: text, font: font, isSweeping: false, reduceMotion: false)
        #expect(highlight.isHidden)
        #expect(mask.animation(forKey: "notch.searchlight") == nil)
    }

    private static func labelLayer(
        named name: String,
        in view: NSView
    ) throws -> CALayer {
        let sublayers = try #require(view.layer?.sublayers)
        return try #require(sublayers.first { $0.name == name })
    }

    @Test @MainActor
    func notchLabelHandsALongerReadingToAShorterOneWithoutStretchingIt() throws {
        // Collapsing turns `Approval needed` into `Approval` while the width
        // underneath the label is still animating down from the longer one. The
        // glyph layer used to be framed to `bounds`, so the short raster was
        // stretched across the long frame for the whole transition: the word
        // arrived as wide as the one it replaced and then squeezed into itself.
        //
        // The glyphs are framed to their own raster now, and the word that was
        // dropped dissolves out over the top of them instead.
        let font = NSFont.systemFont(ofSize: 13, weight: .light)
        let expanded = "Approval needed"
        let compact = "Approval"
        let view = SweepingLabelView()
        view.apply(text: expanded, font: font, isSweeping: true, reduceMotion: false)
        view.frame = NSRect(origin: .zero, size: view.intrinsicContentSize)
        view.layout()

        let expandedWidth = view.intrinsicContentSize.width
        let compactWidth = ceil(
            (compact as NSString).size(withAttributes: [.font: font]).width
        )
        #expect(compactWidth < expandedWidth)

        // The reading changes first and the layout follows it, so this is the
        // view exactly as it is drawn mid-collapse: new text, old frame.
        view.apply(text: compact, font: font, isSweeping: true, reduceMotion: false)
        view.layout()

        let glyphs = try Self.labelLayer(named: SweepingLabelView.baseLayerName, in: view)
        #expect(glyphs.frame.width == compactWidth)
        #expect(glyphs.frame.width < view.bounds.width)

        // The reading being taken away is still drawn, at its own width, and on
        // its way out on the same curve the panel is closing on.
        let outgoing = try Self.labelLayer(
            named: SweepingLabelView.outgoingLayerName,
            in: view
        )
        #expect(outgoing.contents != nil)
        #expect(outgoing.frame.width == expandedWidth)
        let fadeOut = try #require(
            outgoing.animation(forKey: SweepingLabelView.dissolveAnimationKey)
                as? CABasicAnimation
        )
        #expect(fadeOut.duration == PanelMotion.duration)
        #expect(fadeOut.toValue as? Float == 0)
        // It rests invisible, so there is nothing to tear down on a timer.
        #expect(outgoing.opacity == 0)

        // `Approval` is the beginning of `Approval needed`: those glyphs are the
        // same pixels in the same place, and fading a second copy in over them
        // would only dim a word that never moved.
        #expect(glyphs.animation(forKey: SweepingLabelView.dissolveAnimationKey) == nil)

        // The tail is drawn past the view for as long as it is leaving, so the
        // closing edge has to be what cuts it off -- otherwise those glyphs are
        // outside the black surface and over the desktop.
        #expect(view.layer?.masksToBounds == true)
    }

    @Test @MainActor
    func notchLabelCrossFadesTwoUnrelatedReadings() throws {
        // `Running` and `Approval` share nothing, so the new reading has to
        // arrive as well as the old one leaving. Shown at full strength, as the
        // shared-prefix case deliberately does, it would stamp itself over the
        // copy still dissolving underneath it.
        let font = NSFont.systemFont(ofSize: 13, weight: .light)
        let view = SweepingLabelView()
        view.apply(text: "Running", font: font, isSweeping: true, reduceMotion: false)
        view.frame = NSRect(origin: .zero, size: view.intrinsicContentSize)
        view.layout()

        view.apply(text: "Approval", font: font, isSweeping: true, reduceMotion: false)
        view.layout()

        let glyphs = try Self.labelLayer(named: SweepingLabelView.baseLayerName, in: view)
        let fadeIn = try #require(
            glyphs.animation(forKey: SweepingLabelView.dissolveAnimationKey)
                as? CABasicAnimation
        )
        #expect(fadeIn.fromValue as? Float == 0)
        #expect(fadeIn.toValue as? Float == 1)
        #expect(fadeIn.duration == PanelMotion.duration)

        // Reduce Motion shortens the hand-over rather than removing it: a
        // dissolve is what that setting asks for in place of movement.
        view.apply(text: "Running", font: font, isSweeping: true, reduceMotion: true)
        let outgoing = try Self.labelLayer(
            named: SweepingLabelView.outgoingLayerName,
            in: view
        )
        let reduced = try #require(
            outgoing.animation(forKey: SweepingLabelView.dissolveAnimationKey)
                as? CABasicAnimation
        )
        #expect(reduced.duration == PanelMotion.reducedDuration)
    }

    /// The store is the only writer any of that motion has.
    ///
    /// Every reduced path above -- the dissolve, the matrix keyframes, the
    /// panel's spring -- reads `MonitorStore.reduceMotion` and nothing else,
    /// and it was declared `false` and never assigned, so all of them were
    /// dead in production while tests that hand the flag straight to a view
    /// went on passing. This one fails if the property loses its writer.
    @Test @MainActor
    func reduceMotionIsReadFromTheSystemAndFollowsItsChanges() async {
        let accessibility = NotificationCenter()
        let systemSetting = MutableFlag(true)
        let store = MonitorStore(
            services: [],
            systemReduceMotion: { systemSetting.value },
            accessibilityNotifications: accessibility
        )

        // Read at construction, because this is a state rather than an event:
        // a user who already had Reduce Motion on never posts a change for it.
        #expect(store.reduceMotion)

        systemSetting.value = false
        accessibility.post(
            name: NSWorkspace.accessibilityDisplayOptionsDidChangeNotification,
            object: nil
        )
        // The workspace posts one notification for the whole accessibility
        // group and the store re-reads; the hop to the main actor is what
        // these yields are waiting on.
        for _ in 0 ..< 24 where store.reduceMotion {
            await Task.yield()
        }
        #expect(store.reduceMotion == false)
    }

    private static func alphaExtremes(
        of image: CGImage
    ) throws -> (minimum: Double, maximum: Double) {
        let width = image.width
        let height = image.height
        var pixels = [UInt8](repeating: 0, count: width * height * 4)
        let drew = pixels.withUnsafeMutableBytes { buffer -> Bool in
            guard let context = CGContext(
                data: buffer.baseAddress,
                width: width,
                height: height,
                bitsPerComponent: 8,
                bytesPerRow: width * 4,
                space: CGColorSpaceCreateDeviceRGB(),
                bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
            ) else {
                return false
            }
            context.draw(
                image,
                in: CGRect(x: 0, y: 0, width: width, height: height)
            )
            return true
        }
        try #require(drew)

        let alphas = stride(from: 3, to: pixels.count, by: 4).map {
            Double(pixels[$0]) / 255
        }
        return (alphas.min() ?? 1, alphas.max() ?? 0)
    }

    @Test @MainActor
    func sessionRowTextFadesItsOverflowThroughCoreAnimation() throws {
        // This row owns the trailing fade its caller used to apply as a SwiftUI
        // mask. Getting it wrong is silent -- a row that clips hard instead of
        // fading -- so it is asserted on the layer.
        let font = NSFont.systemFont(ofSize: 13, weight: .light)
        let text = "A preview long enough to run past the row it is drawn in"
        let view = SessionRowTextView()
        view.apply(
            text: text,
            font: font,
            color: NotchPalette.labelDrawingColor
        )

        // Narrower than the glyphs, which is the case the fade exists for.
        let glyphWidth = view.intrinsicContentSize.width
        let rowWidth = glyphWidth / 2
        view.frame = NSRect(x: 0, y: 0, width: rowWidth, height: 18)
        view.layout()

        let root = try #require(view.layer)
        let sublayers = try #require(root.sublayers)
        // One layer, not two: the bright swept copy the row used to carry is
        // gone, so live progress text is drawn once and left still.
        #expect(sublayers.count == 1)

        // Only what the row can show is drawn. The remainder sits behind the
        // fade, so drawing it would upload a texture per update for pixels that
        // are never composited -- and body text is replaced as a turn runs.
        let glyphs = try #require(sublayers.first)
        #expect(glyphs.frame.width == rowWidth)
        #expect(glyphs.frame.width < glyphWidth)
        let contents = try #require(glyphs.contents)
        let image = unsafeDowncast(contents as AnyObject, to: CGImage.self)
        let alphas = try Self.alphaExtremes(of: image)
        #expect(alphas.minimum == 0)
        #expect(alphas.maximum > 0.5)

        // The fade covers the row and turns transparent over its last stretch.
        let fade = try #require(root.mask as? CAGradientLayer)
        #expect(fade.frame.width == rowWidth)
        let locations = try #require(fade.locations)
        #expect(locations.count == 3)
        let fadeStart = try #require(locations.dropFirst().first).doubleValue
        #expect(fadeStart > 0)
        #expect(fadeStart < 1)
    }

    @Test @MainActor
    func elapsedTicksDoNotRepublishTheStore() async throws {
        // Every publish on the store re-evaluates the whole overlay, profiled at
        // roughly 20ms. A readout advancing a second must not cost that: it used
        // to, and a turn sitting on an approval burned ~4% of a core doing
        // nothing but redrawing four characters. The readouts now take the tick
        // directly, so a second passing must be silent here.
        let clock = TestClock()
        let store = makeIdleStore(clock: clock)
        let startedAt = clock.now()
        store.applyForTesting(
            makeSessionSnapshot([
                makeSession(status: .approvalNeeded, startedAt: startedAt)
            ]),
            observedAt: clock.now()
        )
        await clock.settle()

        var publishes = 0
        let subscription = store.objectWillChange.sink { _ in publishes += 1 }
        defer { subscription.cancel() }

        // Nine seconds, every one of them a new reading, none of them a new
        // width: 0:01 through 0:09 are all four characters.
        await clock.advance(by: 9)
        #expect(store.compactTimerText == "0:09")
        #expect(
            publishes == 0,
            "a tick republished the store \(publishes) time(s)"
        )

        // Crossing into 10:00 does change the reserved width, and the panel has
        // to re-measure for that -- so exactly here a publish is expected.
        await clock.advance(by: 591)
        #expect(store.compactTimerText == "10:00")
        #expect(publishes > 0, "a width change must reach the panel")
    }

    @Test @MainActor
    func refreshLoopNeverSpinsOnAnOverdueDeadline() async throws {
        // The store cannot verify a service's deadlines, so it must stay bounded
        // when one is wrong. Without a floor an overdue deadline sleeps zero and
        // the loop runs full snapshots continuously -- measured at 63% of a core
        // with the main thread inside a synchronous LaunchServices round trip.
        let clock = TestClock()
        let timing = MonitorTiming.standard
        let service = StuckDeadlineMonitoringStub(
            deadline: clock.now().addingTimeInterval(-5)
        )
        let store = MonitorStore(
            displays: [
                makeDisplay(
                    id: "display-1",
                    ordinal: 1,
                    menuBarHeight: 38,
                    hasNotch: true
                )
            ],
            services: [service],
            initialSnapshot: .connecting,
            clock: clock,
            timing: timing
        )

        for _ in 0 ..< 8 {
            await clock.advance(by: timing.minimumRefreshInterval)
        }

        let requested = clock.requestedSleepIntervals
        #expect(!requested.isEmpty)
        #expect(requested.allSatisfy { $0 >= timing.minimumRefreshInterval })
        // Bounded work, not "no work": the loop still converges on the deadline.
        #expect(await service.snapshotCount() <= 10)
        store.stopMonitoring()
    }

    @Test @MainActor
    func refreshDeadlineNeverFallsIntoThePast() async throws {
        // The store sleeps `max(0, deadline - now)`, so a deadline the service
        // can never advance is not a late wake-up -- it is a zero-length sleep
        // in an unconditional loop, i.e. a busy loop running full snapshots.
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let installer = CodexHookRegistrar(paths: paths)
        let clock = TestClock()
        let timing = MonitorTiming.standard
        let repository = HookEventRepository(
            paths: paths,
            clock: clock,
            timing: timing
        )
        try await installer.install()
        try JSONSerialization.data(withJSONObject: [
            "received_at": Date().timeIntervalSince1970,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-hooked",
            "turn_id": "turn-hooked"
        ]).deliver(to: repository)

        // Only `thread-hooked` is driven by a Hook. `thread-idle` is an ordinary
        // unarchived thread -- the state of every real account.
        let client = CodexAppServerStub(
            listedThreads: [
                .object([
                    "id": .string("thread-hooked"),
                    "ephemeral": .bool(false),
                    "threadSource": .string("user"),
                    "name": .string("Hooked")
                ]),
                .object([
                    "id": .string("thread-idle"),
                    "ephemeral": .bool(false),
                    "threadSource": .string("user"),
                    "name": .string("Idle")
                ])
            ],
            loadedListResults: []
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            clock: clock,
            timing: timing,
            desktopProcessIdentifierProvider: { 4_242 }
        )

        _ = await service.fetchSnapshot()
        await waitForThreadListRequests(client, atLeast: 1, completed: true)
        await waitForThreadReads(client, atLeast: 1)

        // Past the per-thread metadata window, still inside the membership one.
        await clock.advance(by: timing.threadMetadataRefreshInterval + 1)
        _ = await service.fetchSnapshot()
        await waitForThreadReads(client, atLeast: 2)

        let deadline = try #require(await service.nextRefreshDeadline())
        #expect(deadline >= clock.now())
        await service.disconnect()
    }

    @Test @MainActor
    func backgroundReadsHonourTheirOwnFreshnessWindows() async throws {
        // These windows previously had no coverage at all: every one of them was
        // a bare Date() comparison, so nothing could state when a background
        // read actually repeats. With an injected clock they are exact.
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let installer = CodexHookRegistrar(paths: paths)
        let clock = TestClock()
        let timing = MonitorTiming.standard
        let repository = HookEventRepository(
            paths: paths,
            clock: clock,
            timing: timing
        )
        try await installer.install()

        var eventIndex = 0
        func emitHookActivity() throws {
            eventIndex += 1
            let event: [String: Any] = [
                "received_at": clock.now().timeIntervalSince1970,
                "hook_event_name": eventIndex == 1 ? "UserPromptSubmit" : "PostToolUse",
                "session_id": "thread-window",
                "turn_id": "turn-window",
                "tool_name": "Bash",
                "tool_use_id": "exec-\(eventIndex)"
            ]
            try JSONSerialization.data(withJSONObject: event).deliver(to: repository)
        }

        let client = CodexAppServerStub(
            listedThreads: [.object([
                "id": .string("thread-window"),
                "ephemeral": .bool(false),
                "threadSource": .string("user"),
                "name": .string("Windowed")
            ])],
            loadedListResults: []
        )
        let service = LiveCodexMonitorService(
            client: client,
            hookEvents: repository,
            hookRegistrar: installer,
            clock: clock,
            timing: timing,
            desktopProcessIdentifierProvider: { 4_242 }
        )

        try emitHookActivity()
        _ = await service.fetchSnapshot()
        await waitForThreadListRequests(client, atLeast: 1, completed: true)
        await waitForThreadReads(client, atLeast: 1)
        #expect(await client.requestCount(method: "thread/list") == 1)
        #expect(await client.requestCount(method: "thread/read") == 1)

        // Just short of each window: plenty of Hook activity, no repeat reads.
        await clock.advance(by: timing.threadMetadataRefreshInterval - 1)
        try emitHookActivity()
        _ = await service.fetchSnapshot()
        await clock.settle()
        #expect(await client.requestCount(method: "thread/read") == 1)
        #expect(await client.requestCount(method: "thread/list") == 1)

        // Past the metadata window only: the cheap read repeats, the expensive
        // membership pagination still does not.
        await clock.advance(by: 2)
        try emitHookActivity()
        _ = await service.fetchSnapshot()
        await waitForThreadReads(client, atLeast: 2)
        #expect(await client.requestCount(method: "thread/list") == 1)

        // Past the membership window: the full list repeats exactly once.
        await clock.advance(by: timing.threadListRefreshInterval)
        try emitHookActivity()
        _ = await service.fetchSnapshot()
        await waitForThreadListRequests(client, atLeast: 2, completed: true)
        #expect(await client.requestCount(method: "thread/list") == 2)

        await service.disconnect()
    }

    @Test @MainActor
    func hookActivityReadsOnlyItsOwnThreadsInsteadOfTheWholeList() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }

        let installer = CodexHookRegistrar(paths: paths)
