    /// The definition never changes, and this is the pin that says so.
    ///
    /// Codex stores trust in `config.toml` under
    /// `[hooks.state."<hooks.json path>:<event>:<group>:<handler>"]`, keyed by
    /// the definition's content hash. Change a definition and Codex **silently
    /// stops executing that one** until the user re-trusts it in `/hooks`,
    /// while every untouched definition keeps firing normally — so nothing in
    /// the app can see it. Measured on 2026-08-15 with `PreToolUse` dead for
    /// two consecutive turns and no indication anywhere.
    ///
    /// So the handler names a stable path and carries nothing else: no version,
    /// no port, no token, no argument that could ever need to change.
    /// Versioning lives in the script, which is not hashed. This test fails the
    /// build rather than the user's trust when somebody edits either.
    @Test @MainActor
    func theRegisteredDefinitionCarriesNothingThatCouldEverNeedToChange() async throws {
        let paths = makeTemporaryHookPaths()
        defer { try? FileManager.default.removeItem(at: paths.supportDirectory.deletingLastPathComponent()) }

        let registrar = CodexHookRegistrar(paths: paths)
        try await registrar.install()

        let root = try #require(
            JSONSerialization.jsonObject(
                with: try Data(contentsOf: paths.hooksConfiguration)
            ) as? [String: Any]
        )
        let hooks = try #require(root["hooks"] as? [String: Any])
        let expected: [String: Any] = [
            "type": "command",
            "command": "/bin/sh '\(paths.hookHelper.path)'",
            "timeout": 3
        ]

        for definition in CodexHookVocabulary().managedDefinitions {
            let groups = try #require(hooks[definition.event] as? [[String: Any]])
            let group = try #require(groups.last)
            // Unmatched, every one of them. A matcher would put a naming detail
            // in charge of whether a wait is ever observed, and a miss is
            // silent.
            #expect(group["matcher"] == nil)
            let handlers = try #require(group["hooks"] as? [[String: Any]])
            #expect(handlers.count == 1)
            #expect((handlers[0] as NSDictionary) == (expected as NSDictionary))
        }

        // Rewriting the helper -- the whole of how this app ships a change --
        // leaves the registration byte-identical, which is the property the
        // frozen definition exists to provide.
        let before = try Data(contentsOf: paths.hooksConfiguration)
        try Data("#!/bin/sh\n# something else entirely\n".utf8)
            .write(to: paths.hookHelper)
        #expect(await registrar.prepareHelper())
        #expect(try Data(contentsOf: paths.hooksConfiguration) == before)
    }

    /// Two facts with two sources, and the four cards they make.
    ///
    /// `HookSetupStatus` used to be the model as well as the display, which is
    /// what made the reading take the second fact as a parameter and forced
    /// every caller to thread one through the other.
    @Test @MainActor
    func registrationAndDeliveryProjectToTheFourCards() async throws {
        #expect(
            HookSetupStatus.card(registration: .absent, hasObservedEvent: false)
                == .notInstalled
        )
        #expect(
            HookSetupStatus.card(registration: .absent, hasObservedEvent: true)
                == .notInstalled
        )
        // Mismatched says the same thing whatever has been delivered: some of
        // ours is firing, which is exactly why the rest failing is invisible.
        #expect(
            HookSetupStatus.card(registration: .mismatched, hasObservedEvent: false)
                == .repairRequired
        )
        #expect(
            HookSetupStatus.card(registration: .mismatched, hasObservedEvent: true)
                == .repairRequired
        )
        #expect(
            HookSetupStatus.card(registration: .complete, hasObservedEvent: false)
                == .reviewRequired
        )
        #expect(
            HookSetupStatus.card(registration: .complete, hasObservedEvent: true)
                == .active
        )
        // Registered is enough to monitor; only the two unregistered states
        // turn the integration off.
        #expect(HookSetupStatus.reviewRequired.isIntegrationEnabled)
        #expect(HookSetupStatus.active.isIntegrationEnabled)
        #expect(!HookSetupStatus.repairRequired.isIntegrationEnabled)
        #expect(!HookSetupStatus.notInstalled.isIntegrationEnabled)

        // And end to end: a user who trusted the hooks last week is not asked
        // to do it again after a restart.
        let paths = makeTemporaryHookPaths()
        defer { try? FileManager.default.removeItem(at: paths.supportDirectory.deletingLastPathComponent()) }
        let registrar = CodexHookRegistrar(paths: paths)
        #expect(await registrar.registration() == .absent)
        try await registrar.install()

        let fresh = HookEventRepository(paths: paths)
        #expect(HookSetupStatus.card(
            registration: await registrar.registration(),
            hasObservedEvent: await fresh.observedState().hasObservedEvent
        ) == .reviewRequired)

        deliverHook([
            "received_at": Date().timeIntervalSince1970,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "t", "turn_id": "u"
        ], to: fresh)
        _ = await fresh.drainDeliveredEvents()

        let restarted = HookEventRepository(paths: paths)
        #expect(HookSetupStatus.card(
            registration: await registrar.registration(),
            hasObservedEvent: await restarted.observedState().hasObservedEvent
        ) == .active)
    }

    /// Payloads are reduced in the order they landed, over the real socket.
    ///
    /// The transport's whole claim: connections are accepted in arrival order
    /// and handed to one serial read queue, so the reducer sees what the agent
    /// fired in the order it fired. Nothing in the registration provides this —
    /// Claude Code's `command` schema has an `async` key, and using it was
    /// measured to reorder a `PreToolUse` against its own `PostToolUse`
    /// (ADR 0013). The hand-off to the store is where it would be lost again:
    /// two `Task`s spawned in order are not two `Task`s that run in order, so
    /// the inbox is taken whole rather than one payload at a time.
    @Test @MainActor
    func payloadsAreReducedInTheOrderTheyLanded() async throws {
        let root = URL(fileURLWithPath: "/tmp")
            .appendingPathComponent("cin-order-\(UUID().uuidString.prefix(8))")
        defer { try? FileManager.default.removeItem(at: root) }
        let paths = HookIntegrationPaths(
            supportDirectory: root.appendingPathComponent("AS"),
            hooksConfiguration: root.appendingPathComponent(".codex/hooks.json")
        )
        let repository = HookEventRepository(paths: paths)
        let listener = AgentHookListener { body, receivedAt in
            repository.deliver(body, at: receivedAt)
        }
        defer { listener.stop() }
        #expect(listener.start(socketURL: paths.hookSocket))

        // A whole turn, one connection each, in the order Codex fires them.
        // The approval borrows the open call's id, so a reordering anywhere in
        // here produces a different final state rather than the same one late.
        for body in [
            ["hook_event_name": "UserPromptSubmit", "session_id": "s", "turn_id": "t"],
            [
                "hook_event_name": "PreToolUse", "session_id": "s", "turn_id": "t",
                "tool_name": "Bash", "tool_use_id": "call-1"
            ],
            [
                "hook_event_name": "PermissionRequest", "session_id": "s",
                "turn_id": "t", "tool_name": "Bash"
            ]
        ] as [[String: Any]] {
            try send(to: paths.hookSocket, body: body)
        }

        var turns = await waitForReducedTurns(repository, count: 1)
        // All three, in order: the wait only opens if the `PreToolUse` that
        // announced the call was reduced before the approval that borrows its
        // id. A reordering leaves the turn Running for good.
        let paired = await holds {
            turns = await repository.drainDeliveredEvents().turns
            return turns.first?.status == .approvalNeeded
        }
        #expect(paired)
        #expect(turns.first?.pendingApproval?.toolUseID == "call-1")
        #expect(turns.first?.pendingApproval?.isInferred == true)

        // An arrival that is older than what the turn already holds changes
        // nothing, so a late one cannot reopen what a later one closed.
        repository.deliver(
            try JSONSerialization.data(withJSONObject: [
                "hook_event_name": "UserPromptSubmit",
                "session_id": "s", "turn_id": "t-earlier"
            ]),
            at: Date(timeIntervalSince1970: 1)
        )
        turns = (await repository.drainDeliveredEvents()).turns
        #expect(turns.first?.turnID == "t")
        #expect(turns.first?.status == .approvalNeeded)
    }

    /// A subagent outliving its turn leaves the row finished, and still working.
    ///
    /// **The measured shape, 2026-08-22, Codex Desktop against CLI
    /// `0.149.0-alpha.4.1`.** Thread `01a02d08-bace…` spawned
    /// `01a02d0d-e6f6…` at 22:18:01 through the `spawn_agent` tool, the main
    /// agent's turn ended at 22:20:10, and the subagent finished at 22:21:41 —
    /// 91 seconds later.
    ///
    /// Two facts make that sequence dangerous. Codex stamps a subagent's hooks
    /// with the **parent's** `session_id` (its rollout records the parent as
    /// `session_id`, and its stop hooks resolve the parent's transcript path),
    /// and it stamps them with the **subagent's own** `turn_id`. So a
    /// subagent's first `PreToolUse` used to be adopted as a continuation of
    /// the row's turn, which retired the real turn id; the parent's own `Stop`
    /// was then rejected as late, and nothing could ever end what was left —
    /// no hook names that turn id again, the thread is still listed so
    /// membership reconciliation keeps the row, and Codex has no activity read
    /// to settle it. The row said *Running* for good.
    @Test @MainActor
    func aSubagentOutlivingItsTurnLeavesTheRowFinishedAndStillWorking() async throws {
        let paths = makeTemporaryHookPaths()
        defer { try? FileManager.default.removeItem(at: paths.supportDirectory.deletingLastPathComponent()) }
        let repository = HookEventRepository(paths: paths)

        let parent = "01a02d08-bace"
        let parentTurn = "01a02d0d-4be5"
        let subagentTurn = "01a02d0d-e72c"
        var clock = Date(timeIntervalSince1970: 0)
        func send(_ body: [String: Any], after seconds: TimeInterval) async {
            clock = clock.addingTimeInterval(seconds)
            repository.deliver(
                try! JSONSerialization.data(withJSONObject: body),
                at: clock
            )
            _ = await repository.drainDeliveredEvents()
        }

        await send([
            "hook_event_name": "UserPromptSubmit", "session_id": parent,
            "turn_id": parentTurn, "prompt": "draft the PRD"
        ], after: 1)

        // The spawn is the main agent's own call: no `agent_id`, and it returns
        // immediately, so its close proves only that the spawn was accepted.
        await send([
            "hook_event_name": "PreToolUse", "session_id": parent,
            "turn_id": parentTurn, "tool_name": "spawn_agent",
            "tool_use_id": "call-spawn"
        ], after: 1)
        await send([
            "hook_event_name": "PostToolUse", "session_id": parent,
            "turn_id": parentTurn, "tool_name": "spawn_agent",
            "tool_use_id": "call-spawn"
        ], after: 1)
        await send([
            "hook_event_name": "SubagentStart", "session_id": parent,
            "turn_id": parentTurn, "agent_id": "agent-1",
            "agent_type": "tikzcd_syntax_audit"
        ], after: 1)

        // The subagent's own work, under the parent's session and its own turn.
        for id in ["call-a", "call-b"] {
            await send([
                "hook_event_name": "PreToolUse", "session_id": parent,
                "turn_id": subagentTurn, "agent_id": "agent-1",
                "tool_name": "shell", "tool_use_id": id
            ], after: 1)
            await send([
                "hook_event_name": "PostToolUse", "session_id": parent,
                "turn_id": subagentTurn, "agent_id": "agent-1",
                "tool_name": "shell", "tool_use_id": id
            ], after: 1)
        }

        var turns = await repository.observedState().turns
        // The row's turn is still the one the user started. Nothing a subagent
        // did was allowed to become the thread's turn.
        #expect(turns.first?.turnID == parentTurn)
        #expect(turns.first?.status == .running)

        await send([
            "hook_event_name": "Stop", "session_id": parent,
            "turn_id": parentTurn,
            "last_assistant_message": "Seven decisions to confirm."
        ], after: 1)

        turns = await repository.observedState().turns
        var turn = try #require(turns.first)
        // The main agent's `Stop` lands, and lands on the turn it names.
        #expect(turn.turnID == parentTurn)
        #expect(turn.status == .completed)
        #expect(turn.assistantPreview == "Seven decisions to confirm.")
        #expect(turn.runningSubagentIDs == ["agent-1"])

        var session = try #require(CodexSnapshotParser.session(
            from: turn, thread: codexRootThread(id: parent), projectName: "tikzcd-editor"
        ))
        // Finished, and saying what is still in flight beside it.
        #expect(session.status == .completed)
        #expect(session.showsSubagentChips)
        #expect(session.subagentsStillRunningCount == 1)
        #expect(session.subagentsAwaitingApprovalCount == 0)

        // 91 seconds later on the measurement, and the terminal it arrives with
        // is `SubagentStop` -- `Stop` carries no `agent_id` and never describes
        // a subagent.
        await send([
            "hook_event_name": "SubagentStop", "session_id": parent,
            "turn_id": subagentTurn, "agent_id": "agent-1",
            "last_assistant_message": "Audit complete."
        ], after: 91)

        turn = try #require(await repository.observedState().turns.first)
        #expect(turn.runningSubagentIDs.isEmpty)
        // The subagent's own closing text is not the row's: the row reports its
        // turn, and its turn ended with the main agent's answer.
        #expect(turn.assistantPreview == "Seven decisions to confirm.")
        session = try #require(CodexSnapshotParser.session(
            from: turn, thread: codexRootThread(id: parent), projectName: "tikzcd-editor"
        ))
        #expect(session.status == .completed)
        #expect(!session.showsSubagentChips)
    }

    /// A subagent that is still working while its parent turn is not finished
    /// does not get a mark of its own.
    ///
    /// The row carries one mark and it is the elapsed readout (PRD §10). A
    /// running row is already saying the thread is working, so the count would
    /// be a second mark repeating it; the slot only has something else to say
    /// once the turn's own clock has stopped. Counting is separate from
    /// drawing, so the reducer keeps the set either way.
    @Test @MainActor
    func aRunningRowKeepsTheTimerAsItsOnlyMark() async throws {
        let paths = makeTemporaryHookPaths()
        defer { try? FileManager.default.removeItem(at: paths.supportDirectory.deletingLastPathComponent()) }
        let repository = HookEventRepository(paths: paths)

        var clock = Date(timeIntervalSince1970: 0)
        func send(_ body: [String: Any]) async {
            clock = clock.addingTimeInterval(1)
            repository.deliver(
                try! JSONSerialization.data(withJSONObject: body),
                at: clock
            )
            _ = await repository.drainDeliveredEvents()
        }

        await send([
            "hook_event_name": "UserPromptSubmit", "session_id": "s", "turn_id": "t"
        ])
        await send([
            "hook_event_name": "SubagentStart", "session_id": "s",
            "turn_id": "t", "agent_id": "a1"
        ])
        await send([
            "hook_event_name": "SubagentStart", "session_id": "s",
            "turn_id": "t", "agent_id": "a2"
        ])

        var turn = try #require(await repository.observedState().turns.first)
        #expect(turn.runningSubagentIDs == ["a1", "a2"])
        var session = try #require(CodexSnapshotParser.session(
            from: turn, thread: codexRootThread(id: "s"), projectName: "P"
        ))
        #expect(session.status == .running)
        #expect(session.runningSubagentCount == 2)
        #expect(!session.showsSubagentChips)

        await send([
            "hook_event_name": "Stop", "session_id": "s", "turn_id": "t"
        ])
        turn = try #require(await repository.observedState().turns.first)
        session = try #require(CodexSnapshotParser.session(
            from: turn, thread: codexRootThread(id: "s"), projectName: "P"
        ))
        #expect(session.showsSubagentChips)
        #expect(session.subagentsStillRunningCount == 2)
        #expect(session.subagentsAwaitingApprovalCount == 0)

        // A subagent is not ended by the user typing again, so it survives the
        // turn boundary that the turn it was spawned by does not.
        await send([
            "hook_event_name": "UserPromptSubmit", "session_id": "s", "turn_id": "t2"
        ])
        turn = try #require(await repository.observedState().turns.first)
        #expect(turn.turnID == "t2")
        #expect(turn.runningSubagentIDs == ["a1", "a2"])
    }

    /// A subagent boundary never opens, names or ends a turn.
    ///
    /// Both events carry the *subagent's* `turn_id`, which is a value this
    /// reducer has never held. Routing them through the exact-turn rule would
    /// adopt it -- which is the whole defect -- so they attach to a turn the
    /// thread already has and create none.
    @Test @MainActor
    func aSubagentBoundaryNeverOpensOrEndsATurn() async throws {
        let paths = makeTemporaryHookPaths()
        defer { try? FileManager.default.removeItem(at: paths.supportDirectory.deletingLastPathComponent()) }
        let repository = HookEventRepository(paths: paths)

        repository.deliver(
            try JSONSerialization.data(withJSONObject: [
                "hook_event_name": "SubagentStart", "session_id": "s",
                "turn_id": "sub-turn", "agent_id": "a1"
            ]),
            at: Date(timeIntervalSince1970: 1)
        )
        // Recognised and consumed -- not a payload the store failed to place --
        // and it left no row behind.
        var state = await repository.drainDeliveredEvents()
        #expect(state.turns.isEmpty)
        #expect(state.diagnostic == nil)

        repository.deliver(
            try JSONSerialization.data(withJSONObject: [
                "hook_event_name": "UserPromptSubmit", "session_id": "s", "turn_id": "t"
            ]),
            at: Date(timeIntervalSince1970: 2)
        )
        repository.deliver(
            try JSONSerialization.data(withJSONObject: [
                "hook_event_name": "SubagentStop", "session_id": "s",
                "turn_id": "sub-turn", "agent_id": "a1"
            ]),
            at: Date(timeIntervalSince1970: 3)
        )
        state = await repository.drainDeliveredEvents()
        let turn = try #require(state.turns.first)
        #expect(turn.turnID == "t")
        #expect(turn.status == .running)
        // A stop for a subagent this reducer never saw start removes nothing
        // and ends nothing.
        #expect(turn.runningSubagentIDs.isEmpty)
        #expect(state.diagnostic == nil)
    }

    @Test @MainActor
    func registrationMergesAtTheTailAndAnAlreadyCorrectInstallWritesNothing() async throws {
        let paths = makeTemporaryHookPaths()
        defer { try? FileManager.default.removeItem(at: paths.supportDirectory.deletingLastPathComponent()) }

        try FileManager.default.createDirectory(
            at: paths.hooksConfiguration.deletingLastPathComponent(),
            withIntermediateDirectories: true
        )
        let managedCommand = CodexHookRegistrar.command(forHelper: paths.hookHelper)
        let existing: [String: Any] = [
            "hooks": [
                "Stop": [[
                    "hooks": [[
                        "type": "command",
                        "command": "/usr/bin/true"
                    ], [
                        "type": "command",
                        "command": managedCommand
                    ]]
                ]]
            ]
        ]
        try JSONSerialization.data(
            withJSONObject: existing,
            options: [.prettyPrinted]
        ).write(to: paths.hooksConfiguration)

        let registrar = CodexHookRegistrar(paths: paths)
        try await registrar.install()
        let afterFirstInstall = try Data(contentsOf: paths.hooksConfiguration)

        // Installing over a configuration that is already exactly right writes
        // nothing at all. This is not tidiness: Codex keys hook trust by
        // `<path>:<event>:<group index>:<handler index>` -- measured on this
        // machine, 2026-08-20 -- so every rewrite is a chance to renumber a
        // group and silently drop the trust on the *user's* own definitions.
        try await registrar.install()
        #expect(try Data(contentsOf: paths.hooksConfiguration) == afterFirstInstall)

        let root = try #require(
            JSONSerialization.jsonObject(with: afterFirstInstall) as? [String: Any]
        )
        let hooks = try #require(root["hooks"] as? [String: Any])
        let stopGroups = try #require(hooks["Stop"] as? [[String: Any]])
        let commands = stopGroups.flatMap { group in
            (group["hooks"] as? [[String: Any]] ?? []).compactMap {
                $0["command"] as? String
            }
        }

        #expect(HookSetupStatus.card(
            registration: await registrar.registration(),
            hasObservedEvent: false
        ) == .reviewRequired)
        #expect(commands.contains("/usr/bin/true"))
        #expect(commands.filter { $0 == managedCommand }.count == 1)

        // Ours goes last, for the same trust-key reason: appending cannot
        // renumber a group that is already there.
        let lastGroupCommands = (stopGroups.last?["hooks"] as? [[String: Any]] ?? [])
            .compactMap { $0["command"] as? String }
        #expect(lastGroupCommands == [managedCommand])

        // Seven definitions, and `SessionEnd` is not one of them. It was
        // registered until this design and reduced to nothing: one process
        // launch per session end, and one more definition for the user to
        // trust. The two subagent boundaries earn theirs -- see
        // ``aSubagentOutlivingItsTurnLeavesTheRowFinishedAndStillWorking``.
        #expect(
            Set(hooks.keys) == [
                "UserPromptSubmit", "PermissionRequest",
                "SubagentStart", "SubagentStop",
                "PreToolUse", "PostToolUse", "Stop"
            ]
        )

        // A helper this app did not write, at a path it manages exclusively.
        // There is no marker asking whether it was ours: the answer to both
        // "our own older helper" and "a file we never installed" is the same
        // one, so the launch path simply writes the current script.
        try "#!/bin/sh\nexit 0\n".write(
            to: paths.hookHelper,
            atomically: true,
            encoding: .utf8
        )
        #expect(await registrar.prepareHelper())
        #expect(
            try String(contentsOf: paths.hookHelper, encoding: .utf8)
                == AgentHookHelper.script(socketPath: paths.hookSocket.path)
        )
        // And it did not touch the registration to do it, which is the whole
        // point of putting the version in the script rather than the definition.
        #expect(try Data(contentsOf: paths.hooksConfiguration) == afterFirstInstall)

        try await registrar.uninstall()
        let uninstalledRoot = try #require(
            JSONSerialization.jsonObject(
                with: try Data(contentsOf: paths.hooksConfiguration)
            ) as? [String: Any]
        )
        let uninstalledHooks = try #require(uninstalledRoot["hooks"] as? [String: Any])
        let remainingCommands = (uninstalledHooks["Stop"] as? [[String: Any]] ?? [])
            .flatMap { group in
                (group["hooks"] as? [[String: Any]] ?? []).compactMap {
                    $0["command"] as? String
                }
            }
        #expect(remainingCommands == ["/usr/bin/true"])
    }

    @Test @MainActor
    func hookInstallerRepairsMissingAndAlteredDefinitions() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }

        let installer = CodexHookRegistrar(paths: paths)
        try await installer.install()

        let installedData = try Data(contentsOf: paths.hooksConfiguration)
        var root = try #require(
            JSONSerialization.jsonObject(with: installedData) as? [String: Any]
        )
        var hooks = try #require(root["hooks"] as? [String: Any])
        hooks.removeValue(forKey: "Stop")
        root["hooks"] = hooks
        try JSONSerialization.data(
            withJSONObject: root,
            options: [.prettyPrinted, .sortedKeys]
        ).write(to: paths.hooksConfiguration, options: .atomic)

        await installer.invalidateRegistration()
        #expect(HookSetupStatus.card(registration: await installer.registration(), hasObservedEvent: true) == .repairRequired)

        try await installer.install()

        await installer.invalidateRegistration()
        #expect(HookSetupStatus.card(registration: await installer.registration(), hasObservedEvent: false) == .reviewRequired)
        let repairedData = try Data(contentsOf: paths.hooksConfiguration)
        let repairedRoot = try #require(
            JSONSerialization.jsonObject(with: repairedData) as? [String: Any]
        )
        let repairedHooks = try #require(
            repairedRoot["hooks"] as? [String: Any]
        )
        #expect(repairedHooks.keys.contains("UserPromptSubmit"))
        #expect(repairedHooks.keys.contains("PermissionRequest"))
        #expect(repairedHooks.keys.contains("PreToolUse"))
        #expect(repairedHooks.keys.contains("PostToolUse"))
        #expect(repairedHooks.keys.contains("Stop"))

        var alteredRoot = repairedRoot
        var alteredHooks = repairedHooks
        var preToolGroups = try #require(
            alteredHooks["PreToolUse"] as? [[String: Any]]
        )
        let groupIndex = try #require(preToolGroups.indices.first)
        var preToolGroup = preToolGroups[groupIndex]
        preToolGroup["matcher"] = "request_user_input"
        var handlers = try #require(
            preToolGroup["hooks"] as? [[String: Any]]
        )
        let handlerIndex = try #require(handlers.indices.first)
        handlers[handlerIndex]["timeout"] = 99
        preToolGroup["hooks"] = handlers
        preToolGroups[groupIndex] = preToolGroup
        alteredHooks["PreToolUse"] = preToolGroups
        alteredRoot["hooks"] = alteredHooks
        try JSONSerialization.data(
            withJSONObject: alteredRoot,
            options: [.prettyPrinted, .sortedKeys]
        ).write(to: paths.hooksConfiguration, options: .atomic)

        await installer.invalidateRegistration()
        #expect(HookSetupStatus.card(registration: await installer.registration(), hasObservedEvent: true) == .repairRequired)

        try await installer.install()

        let exactData = try Data(contentsOf: paths.hooksConfiguration)
        let exactRoot = try #require(
            JSONSerialization.jsonObject(with: exactData) as? [String: Any]
        )
        let exactHooks = try #require(exactRoot["hooks"] as? [String: Any])
        let exactGroups = try #require(
            exactHooks["PreToolUse"] as? [[String: Any]]
        )
        let exactGroup = try #require(exactGroups.first)
        let exactHandlers = try #require(
            exactGroup["hooks"] as? [[String: Any]]
        )
        let exactHandler = try #require(exactHandlers.first)

        // PreToolUse is registered catch-all: no tool-name regex may decide
        // whether a wait is observed.
        #expect(exactGroup["matcher"] == nil)
        #expect(exactHandler["timeout"] as? Int == 3)
        await installer.invalidateRegistration()
        #expect(HookSetupStatus.card(registration: await installer.registration(), hasObservedEvent: false) == .reviewRequired)
    }

    /// Captured from a real Desktop approval on 2026-08-15: asking to run a
    /// shell command produces `PreToolUse(Bash, exec-…)`, then
    /// `PermissionRequest(Bash, tool_use_id: null)` ~30ms later, and nothing
    /// else until the human answers. The approval therefore has to borrow the
    /// id of the call still open for that tool -- which is also what closes it.
    @Test
    func commandApprovalPairsPermissionRequestWithTheOpenToolCall() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }

        let timestamp = Date().timeIntervalSince1970
        let repository = HookEventRepository(
            paths: paths
        )

        func write(_ event: [String: Any], _ index: Int) throws {
            try JSONSerialization.data(withJSONObject: event).deliver(to: repository)
        }

        try write([
            "received_at": timestamp,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-1",
            "turn_id": "turn-1"
        ], 0)
        try write([
            "received_at": timestamp + 1,
            "hook_event_name": "PreToolUse",
            "session_id": "thread-1",
            "turn_id": "turn-1",
            "tool_name": "Bash",
            "tool_use_id": "exec-1"
        ], 1)
        // Announced but not asked about yet: an open tool call is not a wait.
        var status = await repository.drainDeliveredEvents().turns.first?.status
        #expect(status == .running)

        try write([
            "received_at": timestamp + 2,
            "hook_event_name": "PermissionRequest",
            "session_id": "thread-1",
            "turn_id": "turn-1",
            "tool_name": "Bash"
        ], 2)
        status = await repository.drainDeliveredEvents().turns.first?.status
        #expect(status == .approvalNeeded)

        try write([
            "received_at": timestamp + 3,
            "hook_event_name": "PostToolUse",
            "session_id": "thread-1",
            "turn_id": "turn-1",
            "tool_name": "Bash",
            "tool_use_id": "exec-1"
        ], 3)
        status = await repository.drainDeliveredEvents().turns.first?.status
        #expect(status == .running)

        try write([
            "received_at": timestamp + 4,
            "hook_event_name": "Stop",
            "session_id": "thread-1",
            "turn_id": "turn-1"
        ], 4)
        status = await repository.drainDeliveredEvents().turns.first?.status
        #expect(status == .completed)
    }

    /// Captured from a real denial on 2026-08-15: denying the same Bash command
    /// produced *no* event for that call -- 67 seconds of silence and then the
    /// turn's `Stop`. The wait must still end, and here `Stop` is what ends it.
    @Test
    func deniedCommandEndsItsWaitAtTheTurnBoundary() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }

        let timestamp = Date().timeIntervalSince1970
        let repository = HookEventRepository(
            paths: paths
        )

        func write(_ event: [String: Any], _ index: Int) throws {
            try JSONSerialization.data(withJSONObject: event).deliver(to: repository)
        }

        try write([
            "received_at": timestamp,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-1",
            "turn_id": "turn-1"
        ], 0)
        try write([
            "received_at": timestamp + 1,
            "hook_event_name": "PreToolUse",
            "session_id": "thread-1",
            "turn_id": "turn-1",
            "tool_name": "Bash",
            "tool_use_id": "exec-1"
        ], 1)
        try write([
            "received_at": timestamp + 2,
            "hook_event_name": "PermissionRequest",
            "session_id": "thread-1",
            "turn_id": "turn-1",
            "tool_name": "Bash"
        ], 2)
        var status = await repository.drainDeliveredEvents().turns.first?.status
        #expect(status == .approvalNeeded)

        // Denied: `exec-1` is never mentioned again.
        try write([
            "received_at": timestamp + 67,
            "hook_event_name": "Stop",
            "session_id": "thread-1",
            "turn_id": "turn-1"
        ], 3)
        status = await repository.drainDeliveredEvents().turns.first?.status
        #expect(status == .completed)
    }

    /// Denying and then letting the agent try something else: the denied call is
    /// never closed, so the next call's activity is what proves the human
    /// answered. Without this the row claims it is still asking for the rest of
    /// the turn.
    @Test
    func denialFollowedByAnotherToolReturnsToRunning() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }

        let timestamp = Date().timeIntervalSince1970
        let repository = HookEventRepository(
            paths: paths
        )

        func write(_ event: [String: Any], _ index: Int) throws {
            try JSONSerialization.data(withJSONObject: event).deliver(to: repository)
        }

        try write([
            "received_at": timestamp,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-1",
            "turn_id": "turn-1"
        ], 0)
        try write([
            "received_at": timestamp + 1,
            "hook_event_name": "PreToolUse",
            "session_id": "thread-1",
            "turn_id": "turn-1",
            "tool_name": "Bash",
            "tool_use_id": "exec-1"
        ], 1)
        try write([
            "received_at": timestamp + 2,
            "hook_event_name": "PermissionRequest",
            "session_id": "thread-1",
            "turn_id": "turn-1",
            "tool_name": "Bash"
        ], 2)
        var status = await repository.drainDeliveredEvents().turns.first?.status
        #expect(status == .approvalNeeded)

        // Denied, and the agent tries a different approach.
        try write([
            "received_at": timestamp + 30,
            "hook_event_name": "PreToolUse",
            "session_id": "thread-1",
            "turn_id": "turn-1",
            "tool_name": "Read",
            "tool_use_id": "read-1"
        ], 3)
        status = await repository.drainDeliveredEvents().turns.first?.status
        #expect(status == .running)

        // The new call closing must not resurrect the abandoned approval.
        try write([
            "received_at": timestamp + 31,
            "hook_event_name": "PostToolUse",
            "session_id": "thread-1",
            "turn_id": "turn-1",
            "tool_name": "Read",
            "tool_use_id": "read-1"
        ], 4)
        status = await repository.drainDeliveredEvents().turns.first?.status
        #expect(status == .running)
    }

    /// Denying and then being asked a question. The denied approval is never
    /// closed, so the input wait is the only thing that says the human has
    /// moved on -- and the row has to say *which* answer is owed now, which is
    /// the product's single job. `approvalNeeded -> inputNeeded` used to be
    /// absent from the transition table, so the wait cleared the approval and
    /// the row kept the word `Approval` for the whole of the question.
    @Test
    func denialFollowedByAQuestionAsksForInput() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }

        let timestamp = Date().timeIntervalSince1970
        let repository = HookEventRepository(paths: paths)

        func write(_ event: [String: Any]) throws {
            try JSONSerialization.data(withJSONObject: event).deliver(to: repository)
        }

        try write([
            "received_at": timestamp,
            "hook_event_name": "UserPromptSubmit",
            "session_id": "thread-1",
            "turn_id": "turn-1"
        ])
        try write([
            "received_at": timestamp + 1,
            "hook_event_name": "PreToolUse",
            "session_id": "thread-1",
            "turn_id": "turn-1",
            "tool_name": "Bash",
            "tool_use_id": "exec-1"
        ])
        try write([
            "received_at": timestamp + 2,
            "hook_event_name": "PermissionRequest",
            "session_id": "thread-1",
            "turn_id": "turn-1",
            "tool_name": "Bash"
        ])
        var turn = await repository.drainDeliveredEvents().turns.first
        #expect(turn?.status == .approvalNeeded)

        // Denied, and the agent asks how to proceed instead.
        try write([
            "received_at": timestamp + 30,
            "hook_event_name": "PreToolUse",
            "session_id": "thread-1",
            "turn_id": "turn-1",
            "tool_name": "request_user_input",
            "tool_use_id": "ask-1"
        ])
        turn = await repository.drainDeliveredEvents().turns.first
        #expect(turn?.status == .inputNeeded)
        // The three have to agree: an abandoned approval, an open question,
        // and a word that names the question.
        #expect(turn?.pendingApproval == nil)
        #expect(turn?.pendingInputToolUseID == "ask-1")

        // Answering it returns the turn to Running without resurrecting the
        // approval the human already refused.
        try write([
            "received_at": timestamp + 45,
            "hook_event_name": "PostToolUse",
            "session_id": "thread-1",
            "turn_id": "turn-1",
            "tool_name": "request_user_input",
            "tool_use_id": "ask-1"
        ])
        turn = await repository.drainDeliveredEvents().turns.first
        #expect(turn?.status == .running)
    }

