/// The smallest Thread payload the App Server could hand back for a navigable
/// root thread.
///
/// A row needs one: a Turn whose thread the App Server has never handed over
/// draws nothing, so a test about anything *else* still has to say which thread
/// the Turn is on.
private func codexRootThread(
    id: String,
    name: String? = nil,
    preview: String? = nil
) -> JSONValue {
    var fields: [String: JSONValue] = [
        "id": .string(id),
        "threadSource": .string("user"),
        "ephemeral": .bool(false)
    ]
    if let name { fields["name"] = .string(name) }
    if let preview { fields["preview"] = .string(preview) }
    return .object(fields)
}

/// Whether a pid still names a process this test could signal.
private func processIsAlive(_ pid: pid_t) -> Bool {
    kill(pid, 0) == 0
}

/// Waits for a pid to go away.
///
/// Polled rather than slept through: the kill lands as soon as the actor gets
/// to it, and a fixed wait would either flake or cost the whole bound on every
/// run.
private func processDies(_ pid: pid_t, within seconds: TimeInterval) async -> Bool {
    let deadline = Date().addingTimeInterval(seconds)
    while Date() < deadline {
        if !processIsAlive(pid) { return true }
        try? await Task.sleep(nanoseconds: 20_000_000)
    }
    return !processIsAlive(pid)
}

private actor CodexAppServerStub: CodexAppServerCommunicating {
    private let listedThreads: [JSONValue]
    /// Threads `thread/read` answers for that `thread/list` does not carry.
    ///
    /// The real server has both: a thread is written to disk before its first
    /// Hook fires and reads back immediately, while the paginated list is
    /// filtered by source and may be a page behind -- measured 2026-08-25, an
    /// `exec` thread reads back from an independent App Server and never
    /// appears in `thread/list`.
    private let readableThreads: [JSONValue]
    private let connectResult: Result<Void, CodexAppServerError>
    private var threadListError: CodexAppServerError?
    private var threadListDelayNanoseconds: UInt64
    private var threadReadDelayNanoseconds: UInt64 = 0
    /// How long `thread/items/list` takes to answer.
    ///
    /// The window a re-entrant `fetchSnapshot` lands in. On a quiet machine it
    /// is one actor hop and nothing fits inside it; under load it is long
    /// enough for a whole refresh, which is the only difference between the
    /// duplicate progress read reproducing and not.
    private var turnItemsDelayNanoseconds: UInt64 = 0
    private var threadReadError: CodexAppServerError?
    private var loadedListResults: [Result<JSONValue, CodexAppServerError>]
    private let supportsThreadRead: Bool
    /// Whether this stub answers `thread/items/list` at all.
    ///
    /// Defaults to off, which is the shape of a Codex without the experimental
    /// method: the read is tried once, refused, and never asked again. Every
    /// test that predates the live-progress read therefore keeps the rows it
    /// always had.
    private let supportsTurnItems: Bool
    /// Threads that refuse `thread/items/list` even though the server has it.
    ///
    /// Measured shape: a thread whose `historyMode` is `legacy` answers
    /// `-32601 "thread/items/list is not supported yet"` while `paginated`
    /// threads on the same server answer normally.
    private let legacyHistoryThreadIDs: Set<String>
    /// The items each turn has produced, newest last, by `turnId`.
    private var turnItemsByTurnID: [String: [JSONValue]]
    private var methods: [String] = []
    private var threadListParams: [JSONValue] = []
    private var threadReadParams: [JSONValue] = []
    private var turnItemsParams: [JSONValue] = []
    private var completedThreadListRequests = 0
    /// `thread/read` requests that have *answered*, not just been issued.
    ///
    /// The duplicate a re-entrant refresh queues is dispatched when the read in
    /// flight finishes, so a test that wants to catch it has to be able to wait
    /// for that moment rather than guess at it.
    private var completedThreadReadRequests = 0
    private var disconnects = 0
    private var connects = 0

    init(
        listedThreads: [JSONValue],
        loadedListResults: [Result<JSONValue, CodexAppServerError>],
        readableThreads: [JSONValue] = [],
        threadListDelayNanoseconds: UInt64 = 0,
        connectResult: Result<Void, CodexAppServerError> = .success(()),
        threadListError: CodexAppServerError? = nil,
        supportsThreadRead: Bool = true,
        supportsTurnItems: Bool = false,
        turnItemsByTurnID: [String: [JSONValue]] = [:],
        legacyHistoryThreadIDs: Set<String> = []
    ) {
        self.listedThreads = listedThreads
        self.readableThreads = readableThreads
        self.connectResult = connectResult
        self.threadListError = threadListError
        self.loadedListResults = loadedListResults
        self.threadListDelayNanoseconds = threadListDelayNanoseconds
        self.supportsThreadRead = supportsThreadRead
        self.supportsTurnItems = supportsTurnItems
        self.turnItemsByTurnID = turnItemsByTurnID
        self.legacyHistoryThreadIDs = legacyHistoryThreadIDs
    }

    func connect() async throws {
        connects += 1
        try connectResult.get()
    }

    func request(
        method: String,
        params: JSONValue?,
        timeoutNanoseconds: UInt64?
    ) async throws -> JSONValue {
        methods.append(method)
        switch method {
        case "thread/list":
            threadListParams.append(params ?? .null)
            if let threadListError {
                throw threadListError
            }
            if threadListDelayNanoseconds > 0 {
                try await Task.sleep(
                    nanoseconds: threadListDelayNanoseconds
                )
            }
            completedThreadListRequests += 1
            return .object([
                "data": .array(listedThreads),
                "nextCursor": .null
            ])
        case "thread/read":
            threadReadParams.append(params ?? .null)
            // Ahead of the refusals below, not just the answer: a server takes
            // as long to say it has no such method as it does to say anything
            // else, and a refusal that comes back instantly closes the window
            // this delay exists to hold open.
            if threadReadDelayNanoseconds > 0 {
                try await Task.sleep(nanoseconds: threadReadDelayNanoseconds)
            }
            if let threadReadError {
                throw threadReadError
            }
            guard supportsThreadRead else {
                throw CodexAppServerError.remote(
                    code: -32601,
                    message: "Method not found: thread/read"
                )
            }
            // The real server only populates `turns` when includeTurns is true,
            // so the stub mirrors that: a metadata read never carries turns.
            let requestedID = params?["threadId"]?.stringValue
            guard let thread = (listedThreads + readableThreads).first(
                where: { $0["id"]?.stringValue == requestedID }
            ) else {
                throw CodexAppServerError.remote(
                    code: -32602,
                    message: "Unknown thread"
                )
            }
            completedThreadReadRequests += 1
            var metadata = thread.objectValue ?? [:]
            if params?["includeTurns"]?.boolValue != true {
                metadata["turns"] = .array([])
            }
            return .object(["thread": .object(metadata)])
        case "thread/items/list":
            turnItemsParams.append(params ?? .null)
            if turnItemsDelayNanoseconds > 0 {
                try await Task.sleep(nanoseconds: turnItemsDelayNanoseconds)
            }
            let threadID = params?["threadId"]?.stringValue
            guard supportsTurnItems,
                  !(threadID.map(legacyHistoryThreadIDs.contains) ?? false) else {
                // Both absences arrive as the same code from the real server:
                // a Codex without the experimental method, and a thread whose
                // `historyMode` is `legacy`.
                throw CodexAppServerError.remote(
                    code: -32601,
                    message: "thread/items/list is not supported yet"
                )
            }
            let turnID = params?["turnId"]?.stringValue
            let produced = turnID.flatMap { turnItemsByTurnID[$0] } ?? []
            // The real server returns the newest first when asked to, and the
            // fixtures are written in the order the turn produced them.
            let ordered = params?["sortDirection"]?.stringValue == "desc"
                ? produced.reversed().map { $0 }
                : produced
            let limit = params?["limit"]?.intValue ?? ordered.count
            return .object([
                "data": .array(Array(ordered.prefix(limit))),
                "nextCursor": .null
            ])
        case "thread/loaded/list":
            guard !loadedListResults.isEmpty else {
                throw CodexAppServerError.protocolViolation(
                    "unexpected thread/loaded/list request"
                )
            }
            return try loadedListResults.removeFirst().get()
        case "account/read":
            return .object([
                "account": .object([
                    "type": .string("chatgpt"),
                    "chatgptAccountId": .string("test-account")
                ])
            ])
        case "account/rateLimits/read":
            return .object([
                "rateLimits": .object([
                    "primary": .object([
                        "usedPercent": .number(30)
                    ])
                ])
            ])
        case "account/usage/read":
            return .object([
                "summary": .object([:]),
                "dailyUsageBuckets": .array([])
            ])
        default:
            throw CodexAppServerError.remote(
                code: -32601,
                message: "Unexpected method: \(method)"
            )
        }
    }

    func disconnect() async {
        disconnects += 1
    }

    /// Starts or stops `thread/list` failing part-way through a test, which is
    /// what a transient App Server fault looks like from here.
    func setThreadListError(_ error: CodexAppServerError?) {
        threadListError = error
    }

    /// Starts or stops `thread/read` failing, whatever thread is asked for.
    ///
    /// Separate from the unknown-thread refusal the stub answers by itself: a
    /// refusal is the server *answering* about one thread, and this is the
    /// transport failing, which is not an answer about anything.
    func setThreadReadError(_ error: CodexAppServerError?) {
        threadReadError = error
    }

    func requestedMethods() -> [String] {
        methods
    }

    func requestCount(method: String) -> Int {
        methods.filter { $0 == method }.count
    }

    func recordedThreadListParams() -> [JSONValue] {
        threadListParams
    }

    func recordedThreadReadParams() -> [JSONValue] {
        threadReadParams
    }

    func recordedTurnItemsParams() -> [JSONValue] {
        turnItemsParams
    }

    /// Appends one item to a turn, the way a running turn produces them.
    func appendTurnItem(_ item: JSONValue, toTurn turnID: String) {
        turnItemsByTurnID[turnID, default: []].append(item)
    }

    func completedThreadListRequestCount() -> Int {
        completedThreadListRequests
    }

    func completedThreadReadRequestCount() -> Int {
        completedThreadReadRequests
    }

    func setThreadListDelayNanoseconds(_ delay: UInt64) {
        threadListDelayNanoseconds = delay
    }

    func setThreadReadDelayNanoseconds(_ delay: UInt64) {
        threadReadDelayNanoseconds = delay
    }

    func setTurnItemsDelayNanoseconds(_ delay: UInt64) {
        turnItemsDelayNanoseconds = delay
    }

    func disconnectCount() -> Int {
        disconnects
    }

    /// How many times the transport was asked to come up.
    ///
    /// Every one of these is a `codex app-server` fork-and-exec in the real
    /// client, which is what makes counting them worth doing.
    func connectCount() -> Int {
        connects
    }
}

private actor RecordingAppServerClient: CodexAppServerCommunicating {
    private let base: CodexAppServerClient
    private var methods: [String] = []

    init(base: CodexAppServerClient) {
        self.base = base
    }

    func connect() async throws {
        try await base.connect()
    }

    func request(
        method: String,
        params: JSONValue?,
        timeoutNanoseconds: UInt64?
    ) async throws -> JSONValue {
        methods.append(method)
        return try await base.request(
            method: method,
            params: params,
            timeoutNanoseconds: timeoutNanoseconds
        )
    }

    func disconnect() async {
        await base.disconnect()
    }

    func requestedMethods() -> [String] {
        methods
    }

    func requestCount(method: String) -> Int {
        methods.filter { $0 == method }.count
    }
}

