    /// The reader's own rules, over Claude Desktop's real line shapes.
    @Test @MainActor
    func theDesktopPermissionLogPairsARequestWithItsAnswer() async throws {
        let directory = URL(fileURLWithPath: "/tmp")
            .appendingPathComponent("cin-plog-\(UUID().uuidString.prefix(8))")
        try FileManager.default.createDirectory(
            at: directory, withIntermediateDirectories: true
        )
        defer { try? FileManager.default.removeItem(at: directory) }
        let url = directory.appendingPathComponent("main.log")
        let reader = ClaudeDesktopPermissionLogReader(logURL: url)

        func append(_ text: String) throws {
            let data = Data(text.utf8)
            guard let handle = try? FileHandle(forWritingTo: url) else {
                try data.write(to: url)
                return
            }
            defer { try? handle.close() }
            try handle.seekToEnd()
            try handle.write(contentsOf: data)
        }

        // A file that does not exist yet says nothing, rather than trapping.
        #expect(await reader.answeredAt().isEmpty)

        // Noise, and a dialog that is still open. Neither is an answer.
        try append("""
            2026-08-23 18:10:30 [info] [process-memory] trigger=interval tree_rss_sum=1918MB
            2026-08-23 18:10:40 [info] Emitted tool permission request \
            c930390d-7319-4439-bb26-6c610bede16c for Bash in session \
            local_6c63f909-2261-491f-a6c2-3d1dcbb1e88b
            2026-08-23 18:10:42 [info] [refreshSourceRef] refreshed origin/master in 1492ms

            """)
        #expect(
            await reader.answeredAt().isEmpty,
            "the dialog is up and nobody has answered it"
        )

        // A response for a request whose opening line was never seen. It names
        // no session, so it is attributed to nothing rather than to whichever
        // session happens to be waiting.
        try append("""
            2026-08-23 18:10:43 [info] Received permission response for \
            5b7a7b68-c717-4407-9ea5-0b594f3b0d32: once (tool: Bash)

            """)
        #expect(await reader.answeredAt().isEmpty)

        // The answer, exactly as Claude Desktop writes it.
        try append("""
            2026-08-23 18:10:45 [info] LocalSessions.respondToToolPermission: \
            requestId=c930390d-7319-4439-bb26-6c610bede16c, decision=once, hasUpdatedInput=true
            2026-08-23 18:10:45 [info] Received permission response for \
            c930390d-7319-4439-bb26-6c610bede16c: once (tool: Bash)

            """)
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.dateFormat = "yyyy-MM-dd HH:mm:ss"
        let expected = try #require(formatter.date(from: "2026-08-23 18:10:45"))
        var answered = await reader.answeredAt()
        #expect(answered["local_6c63f909-2261-491f-a6c2-3d1dcbb1e88b"] == expected)

        // And it stays answered: a reading is not the only thing that happens
        // between the answer and the refresh that uses it.
        answered = await reader.answeredAt()
        #expect(answered["local_6c63f909-2261-491f-a6c2-3d1dcbb1e88b"] == expected)
    }

    /// An agent that never announced itself is not a subagent of this thread.
    ///
    /// Both products stamp `agent_id` on agents the user never spawned: Claude
    /// Code's own TUI background agents (three `SubagentStop`s with an empty
    /// `agent_type` and no matching start, plus an agent-stamped `PreToolUse`,
    /// measured 2026-08-23), and the reviewer Codex spawns for
    /// `--approve-for-me`, which has a rollout of its own and no
    /// `SubagentStart` at all.
    @Test @MainActor
    func anInternalAgentsCallIsNotASubagent() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let repository = HookEventRepository(paths: paths)
        let thread = "thread-1"

        func deliver(_ body: [String: Any]) throws {
            try JSONSerialization.data(withJSONObject: body).deliver(to: repository)
        }

        try deliver([
            "received_at": 100.0, "hook_event_name": "UserPromptSubmit",
            "session_id": thread, "turn_id": "turn-1"
        ])
        try deliver([
            "received_at": 101.0, "hook_event_name": "SubagentStart",
            "session_id": thread, "turn_id": "sub-turn", "agent_id": "announced",
            "agent_type": "default"
        ])
        // An agent nothing announced, doing exactly what a real one does.
        try deliver([
            "received_at": 102.0, "hook_event_name": "PreToolUse",
            "session_id": thread, "turn_id": "sub-turn", "agent_id": "internal",
            "tool_name": "Bash", "tool_use_id": "call-1"
        ])
        try deliver([
            "received_at": 102.03, "hook_event_name": "PermissionRequest",
            "session_id": thread, "turn_id": "sub-turn", "agent_id": "internal",
            "tool_name": "Bash"
        ])
        var turn = try #require(await repository.drainDeliveredEvents().turns.first)
        #expect(
            turn.subagentsAwaitingApproval == false,
            "a slot is not evidence that this thread has a subagent"
        )
        #expect(turn.runningSubagentIDs == ["announced"])

        // And its stop, which arrives without a start ever having done, changes
        // neither the count nor anyone else's slot -- nor the stamp that dates
        // when the count last moved, which is the one this used to leak
        // through. See `anInternalForkCannotRedateAFinishedTurn`.
        let beforeTheInternalStop = turn.lastSubagentBoundaryAt
        try deliver([
            "received_at": 103.0, "hook_event_name": "SubagentStop",
            "session_id": thread, "turn_id": "sub-turn", "agent_id": "internal"
        ])
        turn = try #require(await repository.drainDeliveredEvents().turns.first)
        #expect(turn.runningSubagentIDs == ["announced"])
        #expect(turn.subagentsAwaitingApproval == false)
        #expect(
            turn.lastSubagentBoundaryAt == beforeTheInternalStop,
            "a set that did not move has no new last-changed instant"
        )
    }

    /// A row the user has read and finished with cannot be re-dated by a fork
    /// the product ran on its own.
    ///
    /// **The events are real and they arrive minutes late.** Claude Code runs
    /// internal forks on a turn that has already ended -- the prompt
    /// suggestion, and the session recap (`/config` -> `Session recap`) --
    /// and each of them announces itself with no `SubagentStart` and finishes
    /// with a `SubagentStop` carrying `agent_type: ""`, an `agent_id` nothing
    /// ever named, and the *finished* turn's `prompt_id`. Measured 2026-08-26
    /// against CLI `2.1.246`, an interactive pty with every event registered on
    /// a throwaway `--settings`: the suggestion at `Stop` + 3.79 s carrying the
    /// suggested next prompt, and the recap at `Stop` + 183.74 s carrying the
    /// summary — that one with **no user input of any kind**, because it fires
    /// `min(180 s, 0.8 x prompt-cache TTL)` after the turn ends while the
    /// terminal is blurred.
    ///
    /// What that cost is a whole product behaviour rather than a stray field.
    /// ``HookTurnState/terminalBoundaryAt`` takes the later of the two stamps,
    /// and it is what ``TerminalUnreadMembershipGate`` compares to decide a
    /// Turn has ended *again* — the one thing allowed to bring a hidden row
    /// back. So a Completed row the user had read, and which the gate had
    /// hidden for good (CC-024), reappeared unread three minutes later and
    /// stayed until they went back to that terminal.
    @Test @MainActor
    func anInternalForkCannotRedateAFinishedTurn() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let repository = HookEventRepository(
            paths: paths,
            vocabulary: ClaudeCodeHookVocabulary()
        )
        let thread = "4be6467a-4351-403d-ae9e-8b49f4420a32"
        let prompt = "3c635b5b-8123-44cd-92af-7fc9b85d81dc"

        func deliver(_ body: [String: Any]) throws {
            try JSONSerialization.data(withJSONObject: body).deliver(to: repository)
        }

        try deliver([
            "received_at": 100.0, "hook_event_name": "UserPromptSubmit",
            "session_id": thread, "prompt_id": prompt
        ])
        try deliver([
            "received_at": 120.0, "hook_event_name": "Stop",
            "session_id": thread, "prompt_id": prompt,
            "last_assistant_message": "gamma", "background_tasks": []
        ])
        var turn = try #require(await repository.drainDeliveredEvents().turns.first)
        #expect(turn.status == .completed)
        #expect(turn.terminalBoundaryAt == Date(timeIntervalSince1970: 120))

        // The prompt-suggestion fork, 3.79 s after the turn's own terminal.
        try deliver([
            "received_at": 123.79, "hook_event_name": "SubagentStop",
            "session_id": thread, "prompt_id": prompt,
            "agent_id": "a7894b6e8cc77a9b7", "agent_type": "",
            "last_assistant_message": "reply with the single word: delta"
        ])
        // And the recap, 183.74 s after it, with nothing from the user in
        // between.
        try deliver([
            "received_at": 303.74, "hook_event_name": "SubagentStop",
            "session_id": thread, "prompt_id": prompt,
            "agent_id": "aa4fd8235513dca83", "agent_type": "",
            "last_assistant_message": "We've been testing single-word replies."
        ])
        turn = try #require(await repository.drainDeliveredEvents().turns.first)
        #expect(turn.runningSubagentIDs.isEmpty)
        #expect(turn.lastSubagentBoundaryAt == nil)
        #expect(
            turn.terminalBoundaryAt == Date(timeIntervalSince1970: 120),
            "the row's Turn ended once, at its own Stop"
        )
        // The turn's own stamp is untouched too, exactly as it is for every
        // other agent-stamped event: this is not the turn doing anything.
        #expect(turn.lastEventAt == Date(timeIntervalSince1970: 120))
        #expect(turn.turnID == prompt)

        // A subagent this thread really did announce still moves the window,
        // which is the whole reason the stamp exists.
        try deliver([
            "received_at": 400.0, "hook_event_name": "SubagentStart",
            "session_id": thread, "prompt_id": prompt,
            "agent_id": "real", "agent_type": "general-purpose"
        ])
        try deliver([
            "received_at": 500.0, "hook_event_name": "SubagentStop",
            "session_id": thread, "prompt_id": prompt,
            "agent_id": "real", "agent_type": "general-purpose"
        ])
        turn = try #require(await repository.drainDeliveredEvents().turns.first)
        #expect(turn.runningSubagentIDs.isEmpty)
        #expect(turn.terminalBoundaryAt == Date(timeIntervalSince1970: 500))
    }

    /// The manual exit survives the new state.
    ///
    /// The row is Completed even while the collapsed surface says `Approval
    /// needed` for it, and `PRD.md` §9.3 keeps the secondary click on exactly
    /// that: what the user has decided they are done with outranks anything
    /// this app knows.
    @Test @MainActor
    func aRowWithASubagentAwaitingApprovalIsStillDismissable() async throws {
        let clock = TestClock()
        let store = makeIdleStore(clock: clock)
        store.applyForTesting(
            makeSessionSnapshot([
                makeSession(
                    status: .completed,
                    startedAt: clock.now().addingTimeInterval(-60),
                    runningSubagentCount: 1,
                    subagentsAwaitingApproval: true
                )
            ]),
            observedAt: clock.now()
        )
        await clock.settle()
        #expect(store.status == .approvalNeeded)
        #expect(
            store.compactTrailingReading
                == CompactTrailingReading(chips: SubagentChipCounts(attention: 1)),
            "no turn is being timed"
        )

        let waiting = try #require(store.sessions.first)
        #expect(waiting.status == .completed)
        #expect(store.dismiss(waiting))
        #expect(store.sessions.isEmpty)
        // With the row gone the surface reports presence again, and the slot it
        // was writing the count into is empty.
        #expect(store.status == .connected)
        #expect(store.compactTrailingReading == .empty)
    }

    /// The same silence, on the main thread, where it was being trusted not to
    /// exist.
    ///
    /// `ClaudeCodeHookVocabulary.reportsApprovalDenials` said this product
    /// reported its own refusals, on the strength of `PermissionDenied`
    /// carrying a `tool_use_id`. Measured 2026-08-23: that event has one emit
    /// site and it is gated on the auto-mode classifier, so a human's `No`
    /// produces nothing whatsoever — and the row went on saying `Approval
    /// needed` until the session-status reading retired the turn, up to a
    /// 30-second poll later, or never for a desktop-hosted session.
    @Test @MainActor
    func aRefusedMainThreadCallStopsSayingApprovalNeeded() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let repository = HookEventRepository(
            paths: paths,
            vocabulary: ClaudeCodeHookVocabulary()
        )
        let thread = "session-1"
        let prompt = "prompt-1"

        func deliver(_ body: [String: Any]) throws {
            try JSONSerialization.data(withJSONObject: body).deliver(to: repository)
        }

        try deliver([
            "received_at": 100.0, "hook_event_name": "UserPromptSubmit",
            "session_id": thread, "prompt_id": prompt
        ])
        try deliver([
            "received_at": 101.0, "hook_event_name": "PreToolUse",
            "session_id": thread, "prompt_id": prompt,
            "tool_name": "Bash", "tool_use_id": "call-1"
        ])
        try deliver([
            "received_at": 101.03, "hook_event_name": "PermissionRequest",
            "session_id": thread, "prompt_id": prompt, "tool_name": "Bash"
        ])
        var turn = try #require(await repository.drainDeliveredEvents().turns.first)
        #expect(turn.status == .approvalNeeded)
        #expect(turn.pendingApproval?.isInferred == true)

        // Refused. Nothing names `call-1` again, ever. The turn carries on, and
        // the next thing it does is the only evidence there will be.
        try deliver([
            "received_at": 160.0, "hook_event_name": "PreToolUse",
            "session_id": thread, "prompt_id": prompt,
            "tool_name": "Read", "tool_use_id": "call-2"
        ])
        turn = try #require(await repository.drainDeliveredEvents().turns.first)
        #expect(turn.pendingApproval == nil)
        #expect(turn.status == .running)
    }
}

extension NotchlineTests {
    /// The tenth of a second between a subagent stopping and its parent's next
    /// turn opening, and what the row says during it.
    ///
    /// Replays the sequence measured on 2026-08-23 against CLI 2.1.241 (a pty
    /// session, the gap at 50 ms; a `-p` run put it at 130 ms). The count goes
    /// to zero at `SubagentStop` and the thread is not finished — Claude Code
    /// re-enters the parent with a prompt of its own, and its `Stop` said so in
    /// advance. Without the pause the row reported `Completed` here and
    /// `Running` again immediately after, which is the flicker this exists to
    /// remove.
    @Test @MainActor
    func aTurnPausedForItsSubagentDoesNotSayFinishedBetweenTheTwo() async throws {
        let paths = makeTemporaryHookPaths()
        defer {
            try? FileManager.default.removeItem(
                at: paths.supportDirectory.deletingLastPathComponent()
            )
        }
        let repository = HookEventRepository(
            paths: paths,
            vocabulary: ClaudeCodeHookVocabulary()
        )
        let thread = "1396fc6f-217f-4c7a-ac3b-c22d8bd08412"
        let prompt = "1b212120-4d0b-4f0e-9d0a-2a0e6c5f7a11"
        let resumed = "0f4a550c-2a1c-4a25-9a5a-6a4a10d1b7c2"
        let agent = "a48982cefc1e20102"
        let inFlight: [[String: Any]] = [[
            "id": agent, "type": "subagent", "status": "running",
            "description": "Run sleep and reply done",
            "agent_type": "general-purpose"
        ]]

        func deliver(_ body: [String: Any]) throws {
            try JSONSerialization.data(withJSONObject: body).deliver(to: repository)
        }

        func row(_ turn: HookTurnState) -> MonitoredSession {
            MonitoredSession(
                agent: .claudeCode,
                threadID: turn.threadID,
                turnID: turn.turnID,
                projectName: "notchline",
                title: "Untitled",
                preview: nil,
                status: turn.status,
                startedAt: turn.startedAt,
                runningSubagentCount: turn.runningSubagentIDs.count,
                subagentsAwaitingApprovalCount: turn.subagentsAwaitingApprovalCount,
                isPausedForBackgroundWork: turn.pausedForBackgroundWork
            )
        }

        try deliver([
            "received_at": 100.00, "hook_event_name": "UserPromptSubmit",
            "session_id": thread, "prompt_id": prompt
        ])
        try deliver([
            "received_at": 102.96, "hook_event_name": "PreToolUse",
            "session_id": thread, "prompt_id": prompt,
            "tool_name": "Agent", "tool_use_id": "toolu_01Ag"
        ])
        try deliver([
            "received_at": 103.00, "hook_event_name": "SubagentStart",
            "session_id": thread, "prompt_id": prompt,
            "agent_id": agent, "agent_type": "general-purpose"
        ])
        try deliver([
            "received_at": 103.00, "hook_event_name": "PostToolUse",
            "session_id": thread, "prompt_id": prompt,
            "tool_name": "Agent", "tool_use_id": "toolu_01Ag"
        ])
        // The parent's terminal, naming the work it is pausing for.
        try deliver([
            "received_at": 104.93, "hook_event_name": "Stop",
            "session_id": thread, "prompt_id": prompt,
            "background_tasks": inFlight
        ])

        var turn = try #require(await repository.drainDeliveredEvents().turns.first)
        #expect(turn.status == .completed)
        #expect(turn.runningSubagentIDs == [agent])
        #expect(turn.pausedForBackgroundWork)
        #expect(MonitorAggregation.effectiveStatus(of: row(turn)) == .running)

        // The subagent finishes. Its own payload still lists it, which is why
        // nothing here reads that copy of the list.
        try deliver([
            "received_at": 118.05, "hook_event_name": "SubagentStop",
            "session_id": thread, "prompt_id": prompt, "agent_id": agent,
            "agent_type": "general-purpose", "background_tasks": inFlight
        ])
        turn = try #require(await repository.drainDeliveredEvents().turns.first)
        #expect(turn.runningSubagentIDs.isEmpty)
        #expect(turn.status == .completed)
        // The row draws nothing in the trailing slot — its own turn really did
        // finish and it has no subagent left to name — and the thread is still
        // working, so the collapsed summary must not say otherwise.
        #expect(!row(turn).showsSubagentChips)
        #expect(
            MonitorAggregation.effectiveStatus(of: row(turn)) == .running,
            "the parent is re-entered 50 ms from here; Completed is a state the thread is never in"
        )

        // 50 ms later, measured. Claude Code re-enters the parent under a
        // prompt id of its own.
        try deliver([
            "received_at": 118.10, "hook_event_name": "UserPromptSubmit",
            "session_id": thread, "prompt_id": resumed
        ])
        turn = try #require(await repository.drainDeliveredEvents().turns.first)
        #expect(turn.turnID == resumed)
        #expect(turn.status == .running)
        // The pause belonged to the turn that wrote it, so the new turn starts
        // without one rather than inheriting it.
        #expect(!turn.pausedForBackgroundWork)

        // And the terminal that is a terminal: an empty list is the field's own
        // way of saying nothing is in flight.
        try deliver([
            "received_at": 121.22, "hook_event_name": "Stop",
            "session_id": thread, "prompt_id": resumed,
            "background_tasks": [[String: Any]]()
        ])
        turn = try #require(await repository.drainDeliveredEvents().turns.first)
        #expect(turn.status == .completed)
        #expect(!turn.pausedForBackgroundWork)
        #expect(MonitorAggregation.effectiveStatus(of: row(turn)) == .completed)
    }

    /// A `Stop` with nothing in flight, and a `Stop` from the product that has
    /// never heard of the field.
    ///
    /// The reverse of the case above, and the reason the pause cannot leak into
    /// ordinary rows: the flag is written by every terminal event, so an empty
    /// list clears one the previous stop set, and an absent field — every Codex
    /// stop, and every Claude Code stop before this field existed — reads as
    /// finished exactly as it always did.
    @Test @MainActor
    func aTerminalThatNamesNoBackgroundWorkIsTheThreadFinishing() async throws {
        for kind in [AnyHookVocabularyCase.codex, .claudeCode] {
            let paths = makeTemporaryHookPaths()
            defer {
                try? FileManager.default.removeItem(
                    at: paths.supportDirectory.deletingLastPathComponent()
                )
            }
            let repository = HookEventRepository(
                paths: paths,
                vocabulary: kind.vocabulary
            )
            let thread = "586df4ed-e1db-4405-bfd4-e9977957b132"

            func deliver(_ body: [String: Any]) throws {
                try JSONSerialization.data(withJSONObject: body).deliver(to: repository)
            }

            try deliver([
                "received_at": 100.0, "hook_event_name": "UserPromptSubmit",
                "session_id": thread, kind.turnKey: "t-1"
            ])
            try deliver([
                "received_at": 101.0, "hook_event_name": "Stop",
                "session_id": thread, kind.turnKey: "t-1"
            ])
            var turn = try #require(await repository.drainDeliveredEvents().turns.first)
            #expect(!turn.pausedForBackgroundWork, "\(kind.name)")
            #expect(turn.status == .completed, "\(kind.name)")

            try deliver([
                "received_at": 102.0, "hook_event_name": "UserPromptSubmit",
                "session_id": thread, kind.turnKey: "t-2"
            ])
            try deliver([
                "received_at": 103.0, "hook_event_name": "Stop",
                "session_id": thread, kind.turnKey: "t-2",
                "background_tasks": [[String: Any]]()
            ])
            turn = try #require(await repository.drainDeliveredEvents().turns.first)
            #expect(!turn.pausedForBackgroundWork, "\(kind.name)")
            #expect(turn.status == .completed, "\(kind.name)")
        }
    }

    /// The one list the payload carries is carried whole or not at all.
    ///
    /// A list cannot be shortened the way the row's text can — half of one is
    /// not JSON, and "how many are left" is the entire reading — so the two
    /// answers are the whole list and no field. Losing the field costs the
    /// pause and nothing else: the row reaches `Completed` a moment early,
    /// which is where it was before the field was read at all.
    @Test @MainActor
    func aListTooLongToCarryIsLeftOutRatherThanCutShort() throws {
        func payload(taskCount: Int, description: String) throws -> Data {
            try JSONSerialization.data(withJSONObject: [
                "hook_event_name": "Stop",
                "session_id": "s-1",
                "prompt_id": "p-1",
                "background_tasks": (0 ..< taskCount).map {
                    [
                        "id": "task-\($0)", "type": "subagent",
                        "status": "running", "description": description
                    ]
                }
            ])
        }

        // Comfortably past what an identity may weigh, so this pins the list's
        // own ceiling rather than passing under the one beside it.
        let carried = try #require(
            HookPayload.distilled(
                from: try payload(
                    taskCount: 12,
                    description: String(repeating: "d", count: 200)
                )
            )
        )
        #expect(carried.backgroundTasks?.count == 12)
        #expect(carried.pausesForBackgroundWork)

        let refused = try #require(
            HookPayload.distilled(
                from: try payload(
                    taskCount: 16,
                    description: String(repeating: "d", count: 1_000)
                )
            )
        )
        #expect(refused.backgroundTasks == nil)
        #expect(!refused.pausesForBackgroundWork)
        // The event itself still lands: the turn is what the payload is for.
        #expect(refused.turnID == "p-1")
        #expect(refused.sessionID == "s-1")
    }
}

/// The two vocabularies, and the one payload key they spell differently.
private enum AnyHookVocabularyCase {
    case codex
    case claudeCode

    var vocabulary: any AgentHookVocabulary {
        switch self {
        case .codex: CodexHookVocabulary()
        case .claudeCode: ClaudeCodeHookVocabulary()
        }
    }

    /// Codex calls the turn identity `turn_id`; Claude Code calls it
    /// `prompt_id`. Nothing else in these tests differs between them, which is
    /// the point of running both through the same events.
    var turnKey: String {
        switch self {
        case .codex: "turn_id"
        case .claudeCode: "prompt_id"
        }
    }

    var name: String {
        switch self {
        case .codex: "Codex"
        case .claudeCode: "Claude Code"
        }
    }
}
